#!/bin/bash
#
# =============================================================================
#  GNSS Caster — NTRIP caster (RTK base station) installer for Raspberry Pi
# =============================================================================
#
#  Self-contained installer: a single Bash script that unpacks and configures a
#  complete NTRIP caster on a Raspberry Pi (Ubuntu 24.04/26.04 LTS, Raspberry
#  Pi OS or Debian). It deploys a
#  Flask/waitress web application, a SQLite database, systemd services and an
#  nginx reverse proxy; drives a Unicore UM980 base receiver over Bluetooth
#  (BlueZ/D-Bus); and streams RTCM3 corrections to rovers over NTRIP (port 2101).
#
#  Requirements : root privileges; Raspberry Pi / Ubuntu 24.04 or 26.04 LTS /
#                 Debian; Python 3.11+ (tested on 3.12 and 3.14).
#  Usage        : sudo ./<script>.sh [install|--uninstall|--repair|...]
#                 Run "./<script>.sh --help" for the full list of modes and the
#                 environment-variable options (TLS, ports, fail2ban, ...).
#
#  Version      : see CASTER_VERSION below (single source of truth).
#  Copyright    : (c) 2026 rslpro. All rights reserved.
#  License      : proprietary - not licensed for redistribution.
# =============================================================================

# This installer is written in bash and uses bash-only features (indirect
# expansion, "printf -v", [[ ]], $EUID). Running it as "sh script.sh" would
# execute it under dash on Debian/Ubuntu and fail with confusing errors, so
# re-exec under bash instead. This block is deliberately POSIX-compatible so
# that dash can parse it before handing over.
if [ -z "${BASH_VERSION:-}" ]; then
    if command -v bash >/dev/null 2>&1; then
        exec bash "$0" "$@"
    fi
    echo "ERROR: this installer requires bash, which was not found." >&2
    echo "Install it (apt install bash) and re-run: bash $0" >&2
    exit 1
fi

set -eE

# Product version. This is the single source of truth for the startup banner,
# the --version flag and the runtime "Server: GNSS-Caster/<version>" NTRIP
# header (the latter via the generated app/version.py). Bump on every release.
CASTER_VERSION="3.3.4"

# Basename of this script as invoked, so --help / usage text stays correct even
# if the file is renamed for distribution.
SCRIPT_NAME="$(basename "$0")"

# Answer --version/-v early and quietly, before the install machinery and the
# startup banner run, so the output stays script-friendly.
case "${1:-}" in
    -v|--version)
        echo "gnss-caster $CASTER_VERSION"
        exit 0
        ;;
esac

echo "=== GNSS Caster install/uninstall script v$CASTER_VERSION ==="
echo ""

# ----------------- CONFIGURATION -----------------
# Global paths, service identity and install-time tunables (ports, TLS,
# fail2ban, Bluetooth pairing). Values marked below are overridable via
# environment variables; CASTER_VERSION above is the single version source.
BASE=/opt/gnss-caster
APP=$BASE/app
VENV=$BASE/venv
INST=$BASE/instance
BACKUP_DIR=$BASE/backups
LOG_DIR=/var/log/gnss-caster
SERVICE_USER=gnss-caster
SERVICE_GROUP=gnss-caster
SERVICE=/etc/systemd/system/gnss-caster.service
NGINX_AVAILABLE=/etc/nginx/sites-available/gnss-caster
NGINX_ENABLED=/etc/nginx/sites-enabled/gnss-caster
NGINX_SECURITY_CONF=/etc/nginx/conf.d/gnss-caster-security.conf
FAIL2BAN_FILTER=/etc/fail2ban/filter.d/gnss-caster-auth.conf
FAIL2BAN_JAIL=/etc/fail2ban/jail.d/gnss-caster-auth.local
UFW_APP_PROFILE=/etc/ufw/applications.d/gnss-caster
PRIVILEGED_HELPER=$BASE/gnss-caster-privileged-helper.sh
SUDOERS_FILE=/etc/sudoers.d/gnss-caster
POLKIT_RULE=/etc/polkit-1/rules.d/49-gnss-caster-bluetooth.rules
MAINTENANCE_CRON=/etc/cron.d/gnss-caster-maintenance
BACKUP_CRON=/etc/cron.d/gnss-caster-backup
SECRET_KEY=""
SECRET_DIR="/etc/gnss-caster/secrets"
SECRET_KEY_ENV_FILE="$SECRET_DIR/secret.env"
LEGACY_SECRET_KEY_ENV_FILE="$INST/secret.env"
OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE=/etc/gnss-caster/initial-admin-password
BOOTSTRAP_ADMIN_PASSWORD_FILE=$INST/initial-admin-password
INSTALL_REPORT=$INST/install-report.txt

# TLS configuration
# TLS_MODE: none | selfsigned | letsencrypt
# Examples:
#   TLS_MODE=selfsigned TLS_DOMAIN=caster.local ./<script>.sh
#   TLS_MODE=letsencrypt TLS_DOMAIN=caster.example.com TLS_EMAIL=admin@example.com ./<script>.sh
TLS_MODE_RAW="${TLS_MODE:-}"
if [ -n "$TLS_MODE_RAW" ]; then
    TLS_MODE_SET_BY_USER=1
else
    TLS_MODE_SET_BY_USER=0
fi
TLS_MODE=$(echo "${TLS_MODE_RAW:-none}" | tr '[:upper:]' '[:lower:]')
TLS_DOMAIN="${TLS_DOMAIN:-}"
TLS_EMAIL="${TLS_EMAIL:-}"
TLS_SELF_SIGNED_DAYS="${TLS_SELF_SIGNED_DAYS:-3650}"
# Paths to an already-issued certificate, used when TLS_MODE=existing. The cert
# should be the full chain (leaf + intermediates); the key must match it.
TLS_CERT_FILE="${TLS_CERT_FILE:-}"
TLS_KEY_FILE="${TLS_KEY_FILE:-}"
LE_WEBROOT="/var/www/certbot"
SELF_SIGNED_CERT="/etc/ssl/certs/gnss-caster.crt"
SELF_SIGNED_KEY="/etc/ssl/private/gnss-caster.key"
SSL_CERT_PATH=""
SSL_KEY_PATH=""
NGINX_SERVER_NAME="_"
INSTALL_WEB_PORT="${GNSS_CASTER_WEB_PORT:-8080}"
INSTALL_NTRIP_PORT="${GNSS_CASTER_NTRIP_PORT:-2101}"
ENABLE_FAIL2BAN="${GNSS_CASTER_ENABLE_FAIL2BAN:-0}"
ENABLE_AUTO_UPDATE="${GNSS_CASTER_ENABLE_AUTO_UPDATE:-0}"
FORCE_PORT_KILL="${GNSS_CASTER_FORCE_PORT_KILL:-0}"
ENABLE_WATCHDOG="${GNSS_CASTER_ENABLE_WATCHDOG:-0}"
# Bluetooth pairing controls (stored in secret.env, mode 600, not in the unit).
BT_DEFAULT_PIN="${GNSS_CASTER_BT_DEFAULT_PIN:-0000}"
BT_FALLBACK_PINS="${GNSS_CASTER_BT_FALLBACK_PINS:-1234,1111}"
# BT_AUTO_ACCEPT=1 keeps backward-compatible open pairing; set to 0 to only
# accept devices listed in GNSS_CASTER_BT_ALLOWED_DEVICES (comma separated MACs).
BT_AUTO_ACCEPT="${GNSS_CASTER_BT_AUTO_ACCEPT:-1}"
BT_ALLOWED_DEVICES="${GNSS_CASTER_BT_ALLOWED_DEVICES:-}"
FAIL2BAN_WAS_PRESENT=0
FAIL2BAN_WAS_ACTIVE=0
FAIL2BAN_GNSS_JAIL_WAS_PRESENT=0
FAIL2BAN_DISABLED_BY_INSTALLER=0
BACKUP_CRON_STATUS="default enabled"
LOGROTATE_STATUS="default rotate 30 days"
WATCHDOG_CRON_STATUS="disabled"
ROLLBACK_DIR=""
ROLLBACK_ACTIVE=0
ROLLBACK_ROOT="/var/backups/gnss-caster"
INSTALL_STATE_CAPTURED=0
INSTALL_COMMITTED=0
INSTALL_CASTER_WAS_ACTIVE=0
INSTALL_NGINX_WAS_ACTIVE=0
INSTALL_CASTER_ENABLED="not-found"
INSTALL_HEALTH_WAS_OK=0
INSTALL_HEALTH_URL=""
INSTALL_FAILED_LINE="unknown"

SCRIPT_MODE="${1:-}"

# Purge flag for uninstall: keep data by default, delete everything only when
# explicitly requested via --purge or GNSS_CASTER_PURGE=1.
PURGE_DATA=0
case "${GNSS_CASTER_PURGE:-0}" in
    1|true|yes|on|TRUE|YES|ON)
        PURGE_DATA=1
        ;;
esac
for cli_arg in "$@"; do
    if [ "$cli_arg" = "--purge" ]; then
        PURGE_DATA=1
    fi
done

show_usage() {
cat << EOF
Usage:
  ./$SCRIPT_NAME [install|--uninstall|--reset-admin-password|--diagnose|--status|--repair|--self-test]

Modes:
  install                 Run full installation (default)
  --uninstall             Remove GNSS Caster files and configuration (data preserved by default)
  --reset-admin-password  Reset built-in admin password and rewrite bootstrap credentials
  --diagnose              Collect service, network, and log diagnostics
  --status                Show quick runtime status without changing services
  --repair                Repair permissions, systemd, nginx, cron, logrotate, and DB schema
  --self-test             Run installer/runtime consistency checks without changing services
  --rotate-secrets        Rotate SECRET_KEY (and optionally Bluetooth PIN) and restart the service
  --panic                 Revoke API tokens and web sessions; reset 2FA for ALL admins
  --version, -v           Print the caster version and exit
  --help, -h              Show this help and exit

TLS examples for install mode:
  TLS_MODE=selfsigned TLS_DOMAIN=caster.local ./$SCRIPT_NAME
  TLS_MODE=letsencrypt TLS_DOMAIN=example.com TLS_EMAIL=admin@example.com ./$SCRIPT_NAME
  TLS_MODE=existing TLS_CERT_FILE=/etc/ssl/mycert/fullchain.pem TLS_KEY_FILE=/etc/ssl/mycert/privkey.pem ./$SCRIPT_NAME

Port override example for install mode:
  GNSS_CASTER_WEB_PORT=8081 GNSS_CASTER_NTRIP_PORT=2201 ./$SCRIPT_NAME

Optional fail2ban hardening for install mode:
  GNSS_CASTER_ENABLE_FAIL2BAN=1 ./$SCRIPT_NAME

Optional weekly auto-update for install mode:
  GNSS_CASTER_ENABLE_AUTO_UPDATE=1 ./$SCRIPT_NAME

Optional force-kill occupied runtime port for install mode:
  GNSS_CASTER_FORCE_PORT_KILL=1 ./$SCRIPT_NAME

Optional safe health watchdog cron for install mode:
  GNSS_CASTER_ENABLE_WATCHDOG=1 ./$SCRIPT_NAME

Interactive install uses a whiptail/dialog menu when available on a terminal.
Force plain text prompts with:
  GNSS_CASTER_NO_TUI=1 ./$SCRIPT_NAME

Uninstall examples:
  ./$SCRIPT_NAME --uninstall            # remove /opt/gnss-caster, keep safety backup in /var/backups/gnss-caster
  ./$SCRIPT_NAME --uninstall --purge    # delete everything, including data (no safety backup)

Recovery example:
  ./$SCRIPT_NAME --reset-admin-password

Diagnostics example:
  ./$SCRIPT_NAME --diagnose

Status example:
  ./$SCRIPT_NAME --status

Repair example:
  ./$SCRIPT_NAME --repair

Self-test example:
  sudo ./$SCRIPT_NAME --self-test
EOF
}

# ----------------- INTERACTIVE UI (TUI) -----------------
# Optional ncurses-style front-end for the interactive prompts. Prefers whiptail
# (shipped by default on Raspberry Pi OS / Debian / Ubuntu), then dialog, and
# otherwise falls back to plain text prompts. Only the *configuration questions*
# are dialog-driven; the install itself still streams its log to the terminal so
# errors stay visible. Force plain prompts with GNSS_CASTER_NO_TUI=1.
UI_BIN=""
detect_ui_backend() {
    UI_BIN=""
    [ "${GNSS_CASTER_NO_TUI:-0}" = "1" ] && return
    [ -t 0 ] && [ -t 1 ] || return
    if command -v whiptail >/dev/null 2>&1; then UI_BIN="whiptail"; return; fi
    if command -v dialog >/dev/null 2>&1; then UI_BIN="dialog"; return; fi
}

ui_enabled() { [ -n "$UI_BIN" ]; }

# ui_menu TITLE TEXT tag1 label1 [tag2 label2 ...] -> prints the chosen tag
ui_menu() {
    local title="$1" text="$2"; shift 2
    "$UI_BIN" --title "$title" --menu "$text" 20 76 11 "$@" 3>&1 1>&2 2>&3
}

# ui_input TITLE TEXT [DEFAULT] -> prints the entered text
ui_input() {
    "$UI_BIN" --title "$1" --inputbox "$2" 10 76 "${3:-}" 3>&1 1>&2 2>&3
}

# ui_yesno TITLE TEXT [defaultno] -> exit status 0=yes, 1=no
ui_yesno() {
    local extra=""; [ "${3:-}" = "defaultno" ] && extra="--defaultno"
    "$UI_BIN" --title "$1" $extra --yesno "$2" 12 76
}

# ui_msgbox TITLE TEXT
ui_msgbox() { "$UI_BIN" --title "$1" --msgbox "$2" 16 76; }

# ui_checklist TITLE TEXT tag1 label1 on/off [...] -> prints chosen tags (space-separated)
ui_checklist() {
    local title="$1" text="$2"; shift 2
    "$UI_BIN" --title "$title" --checklist "$text" 18 76 8 "$@" 3>&1 1>&2 2>&3 | tr -d '"'
}

prompt_script_mode() {
    if [ -n "$SCRIPT_MODE" ]; then
        return
    fi

    if [ ! -t 0 ]; then
        SCRIPT_MODE="install"
        return
    fi

    detect_ui_backend

    if ui_enabled; then
        local choice
        choice=$(ui_menu "GNSS Caster $CASTER_VERSION" "Select an operation:" \
            install              "Install or upgrade GNSS Caster" \
            uninstall            "Remove GNSS Caster (data preserved)" \
            reset-admin-password "Reset the admin password" \
            diagnose             "Collect diagnostics" \
            status               "Show runtime status" \
            repair               "Repair an existing installation" \
            self-test            "Run consistency checks" \
            rotate-secrets       "Rotate SECRET_KEY / Bluetooth PIN" \
            panic                "Revoke all API tokens + web sessions + disable 2FA")
        SCRIPT_MODE="${choice:-install}"
        return
    fi

    echo "Select operation mode:"
    echo "  1) install"
    echo "  2) uninstall"
    echo "  3) reset admin password"
    echo "  4) diagnose"
    echo "  5) status"
    echo "  6) repair"
    echo "  7) self-test"
    echo "  8) rotate secrets"
    echo "  9) panic (revoke all API tokens + web sessions + disable all 2FA)"
    echo -n "Enter choice [1-9] (default: 1): "
    read -r mode_choice

    case "$mode_choice" in
        ""|1)
            SCRIPT_MODE="install"
            ;;
        2)
            SCRIPT_MODE="uninstall"
            ;;
        3)
            SCRIPT_MODE="reset-admin-password"
            ;;
        4)
            SCRIPT_MODE="diagnose"
            ;;
        5)
            SCRIPT_MODE="status"
            ;;
        6)
            SCRIPT_MODE="repair"
            ;;
        7)
            SCRIPT_MODE="self-test"
            ;;
        8)
            SCRIPT_MODE="rotate-secrets"
            ;;
        9)
            SCRIPT_MODE="panic"
            ;;
        *)
            echo "ERROR: Invalid choice '$mode_choice'"
            exit 1
            ;;
    esac
}

prompt_tls_mode() {
    if [ "$SCRIPT_MODE" != "install" ]; then
        return
    fi

    if [ "$TLS_MODE_SET_BY_USER" -eq 1 ]; then
        return
    fi

    if [ ! -t 0 ]; then
        return
    fi

    detect_ui_backend
    if ui_enabled; then
        local tls_sel
        tls_sel=$(ui_menu "TLS / HTTPS" "How should the web interface be served?" \
            none        "HTTP only (no TLS)" \
            selfsigned  "HTTPS with a self-signed certificate" \
            letsencrypt "HTTPS with a Let's Encrypt certificate" \
            existing    "HTTPS with a certificate you already have")
        TLS_MODE="${tls_sel:-none}"

        if [ "$TLS_MODE" = "selfsigned" ] && [ -z "$TLS_DOMAIN" ]; then
            TLS_DOMAIN=$(ui_input "Self-signed certificate" "Domain / CN (optional; leave blank to use the hostname):" "")
        fi
        if [ "$TLS_MODE" = "letsencrypt" ]; then
            while [ -z "$TLS_DOMAIN" ]; do
                TLS_DOMAIN=$(ui_input "Let's Encrypt" "Domain (required; must resolve to this host):" "")
            done
            while [ -z "$TLS_EMAIL" ]; do
                TLS_EMAIL=$(ui_input "Let's Encrypt" "Email for the ACME account (required):" "")
            done
        fi
        if [ "$TLS_MODE" = "existing" ]; then
            while [ -z "$TLS_CERT_FILE" ]; do
                TLS_CERT_FILE=$(ui_input "Existing certificate" "Path to the full-chain PEM certificate:" "")
            done
            while [ -z "$TLS_KEY_FILE" ]; do
                TLS_KEY_FILE=$(ui_input "Existing certificate" "Path to the matching private key (PEM):" "")
            done
            if [ -z "$TLS_DOMAIN" ]; then
                TLS_DOMAIN=$(ui_input "Existing certificate" "Server name for nginx (optional):" "")
            fi
        fi
        return
    fi

    echo ""
    echo "Select TLS mode:"
    echo "  1) none (HTTP)"
    echo "  2) selfsigned (HTTPS with self-signed certificate)"
    echo "  3) letsencrypt (HTTPS with trusted certificate)"
    echo "  4) existing (HTTPS with a certificate you already have)"
    echo -n "Enter choice [1-4] (default: 1): "
    read -r tls_choice

    case "$tls_choice" in
        ""|1)
            TLS_MODE="none"
            ;;
        2)
            TLS_MODE="selfsigned"
            ;;
        3)
            TLS_MODE="letsencrypt"
            ;;
        4)
            TLS_MODE="existing"
            ;;
        *)
            echo "ERROR: Invalid TLS choice '$tls_choice'"
            exit 1
            ;;
    esac

    if [ "$TLS_MODE" = "selfsigned" ] && [ -z "$TLS_DOMAIN" ]; then
        echo -n "Enter TLS domain/CN (optional, press Enter to use hostname): "
        read -r TLS_DOMAIN
    fi

    if [ "$TLS_MODE" = "letsencrypt" ]; then
        while [ -z "$TLS_DOMAIN" ]; do
            echo -n "Enter TLS domain (required): "
            read -r TLS_DOMAIN
        done

        while [ -z "$TLS_EMAIL" ]; do
            echo -n "Enter TLS email (required): "
            read -r TLS_EMAIL
        done
    fi

    if [ "$TLS_MODE" = "existing" ]; then
        while [ -z "$TLS_CERT_FILE" ]; do
            echo -n "Enter path to certificate (full-chain PEM): "
            read -r TLS_CERT_FILE
        done
        while [ -z "$TLS_KEY_FILE" ]; do
            echo -n "Enter path to private key (PEM): "
            read -r TLS_KEY_FILE
        done
        if [ -z "$TLS_DOMAIN" ]; then
            echo -n "Enter server name/domain for nginx (optional, press Enter for any): "
            read -r TLS_DOMAIN
        fi
    fi
}

prompt_script_mode

case "$SCRIPT_MODE" in
    install|"")
        SCRIPT_MODE="install"
        ;;
    --uninstall|uninstall)
        SCRIPT_MODE="uninstall"
        ;;
    --purge|purge)
        SCRIPT_MODE="uninstall"
        PURGE_DATA=1
        ;;
    --reset-admin-password|reset-admin-password)
        SCRIPT_MODE="reset-admin-password"
        ;;
    --diagnose|diagnose)
        SCRIPT_MODE="diagnose"
        ;;
    --status|status)
        SCRIPT_MODE="status"
        ;;
    --repair|repair)
        SCRIPT_MODE="repair"
        ;;
    --self-test|self-test)
        SCRIPT_MODE="self-test"
        ;;
    --rotate-secrets|rotate-secrets)
        SCRIPT_MODE="rotate-secrets"
        ;;
    --panic|--revoke-access|panic)
        SCRIPT_MODE="panic"
        ;;
    -h|--help)
        show_usage
        exit 0
        ;;
    *)
        echo "ERROR: Unsupported argument '$SCRIPT_MODE'"
        show_usage
        exit 1
        ;;
esac

strip_crlf() {
    local target="$1"
    if [ -f "$target" ]; then
        sed -i 's/\r$//' "$target" || true
    fi
}

# normalize_bool VAR_NAME ENV_VAR_LABEL
# Accepts 1/true/yes/on -> sets VAR_NAME=1; 0/false/no/off/"" -> sets VAR_NAME=0; else exits.
normalize_bool() {
    local var_name="$1"
    local env_label="$2"
    local val
    val=$(printf '%s' "${!var_name}" | tr '[:upper:]' '[:lower:]')
    case "$val" in
        1|true|yes|on)
            printf -v "$var_name" '%s' "1"
            ;;
        0|false|no|off|"")
            printf -v "$var_name" '%s' "0"
            ;;
        *)
            echo "ERROR: $env_label must be 0/1, true/false, yes/no, or on/off"
            exit 1
            ;;
    esac
}

# ----------------- PRE-FLIGHT CHECKS -----------------
# Validate the host before changing anything: root privileges, OS/arch,
# required commands, port availability, an existing installation and free
# disk space. Fails early with a clear message instead of halfway through.
if [ "$EUID" -ne 0 ]; then 
    echo "ERROR: Please run as root"
    exit 1
fi

# Prevent concurrent installer runs
INSTALL_LOCK_FILE="/run/gnss-caster-installer.lock"
exec 9>"$INSTALL_LOCK_FILE"
if ! flock -n 9; then
    echo "ERROR: Another instance of the GNSS Caster installer is already running (lock: $INSTALL_LOCK_FILE)"
    exit 1
fi
# Leave the lock inode in place. Closing the descriptor on exit releases it;
# unlinking it would let another process lock a different inode at the same path.

EXPECT_BOOTSTRAP_ADMIN_PASSWORD=0
if [ "$SCRIPT_MODE" = "install" ] && [ ! -f "$INST/db.sqlite" ]; then
    EXPECT_BOOTSTRAP_ADMIN_PASSWORD=1
fi

if [ "$SCRIPT_MODE" = "install" ]; then
    normalize_bool ENABLE_FAIL2BAN   "GNSS_CASTER_ENABLE_FAIL2BAN"
    normalize_bool ENABLE_AUTO_UPDATE "GNSS_CASTER_ENABLE_AUTO_UPDATE"
    normalize_bool FORCE_PORT_KILL    "GNSS_CASTER_FORCE_PORT_KILL"
    normalize_bool ENABLE_WATCHDOG    "GNSS_CASTER_ENABLE_WATCHDOG"

    if command -v fail2ban-client >/dev/null 2>&1; then
        FAIL2BAN_WAS_PRESENT=1
    fi

    if [ -f "$FAIL2BAN_JAIL" ]; then
        FAIL2BAN_GNSS_JAIL_WAS_PRESENT=1
    fi

    if command -v systemctl >/dev/null 2>&1 && systemctl is-active --quiet fail2ban; then
        FAIL2BAN_WAS_ACTIVE=1
    fi
fi

backup_and_clear_unit_override() {
    local override_dir="/etc/systemd/system/gnss-caster.service.d"
    if [ -d "$override_dir" ]; then
        local ts
        ts=$(date +%Y%m%d_%H%M%S)
        mkdir -p "$BACKUP_DIR"
        cp -a "$override_dir" "$BACKUP_DIR/systemd-override-$ts" || true
        rm -rf "$override_dir"
    fi
}

acquire_maintenance_lock() {
    local lock_path="/run/gnss-caster-maintenance.lock"
    # Nested update -> backup/restore calls inherit fd 8 and the same lock.
    # Verify the descriptor itself; never trust an environment-variable bypass.
    if [ "$(readlink "/proc/$$/fd/8" 2>/dev/null || true)" != "$lock_path" ]; then
        exec 8>"$lock_path"
    fi
    if ! flock -n 8; then
        echo "ERROR: Another GNSS Caster maintenance operation is running." >&2
        return 1
    fi
    # Do not explicitly unlock: a nested child must not release its parent's lock.
}

ensure_admission_lock() {
    local admission_path="/var/lib/gnss-caster-admission.lock"
    local admission_group=root
    if [ ! -e "$admission_path" ]; then
        (umask 077; set -C; : > "$admission_path") || return 1
    fi
    if [ -L "$admission_path" ] || [ ! -f "$admission_path" ] || \
       [ "$(stat -c %u "$admission_path")" != 0 ] || \
       [ "$(stat -c %h "$admission_path")" != 1 ]; then
        echo "ERROR: Unsafe rover admission lock" >&2
        return 1
    fi
    getent group gnss-caster >/dev/null 2>&1 && admission_group=gnss-caster
    chown root:"$admission_group" "$admission_path"
    chmod 640 "$admission_path"
}

acquire_admission_guard() {
    local admission_path="/var/lib/gnss-caster-admission.lock"
    ensure_admission_lock || return 1
    if [ "$(readlink "/proc/$$/fd/7" 2>/dev/null || true)" != "$admission_path" ]; then
        exec 7<>"$admission_path"
    fi
    if ! flock -n 7; then
        echo "ERROR: Rover admission is busy; try maintenance again" >&2
        return 1
    fi
    # New admissions hold a shared lock until their counter has been committed.
    # Keep our exclusive descriptor until the operation (and rollback) exits.
    python3 -I - << 'PY_ADMISSION_CHECK'
from contextlib import closing
from pathlib import Path
import re
import sqlite3
import sys

base = Path('/opt/gnss-caster')
database = base / 'instance/db.sqlite'
try:
    if not database.exists() and not (base / 'main.py').exists():
        sys.exit(0)  # Fresh installation has no connected clients.
    config = (base / 'instance/config.yaml').read_text(encoding='utf-8')
    configured = re.findall(r'^\s+path:\s*[\'\"]?([^\s\'\"#]+)[\'\"]?\s*(?:#.*)?$', config, re.M)
    if configured != [str(database)]:
        raise ValueError('Maintenance requires the standard database location')
    with closing(sqlite3.connect(database.as_uri() + '?mode=ro', uri=True, timeout=5)) as db:
        active = db.execute('SELECT COALESCE(SUM(active_conn), 0) FROM rover').fetchone()[0]
        if active:
            raise ValueError('Disconnect all rovers before maintenance')
        field = db.execute("SELECT value FROM system_setting WHERE key='field_work_active'").fetchone()
        if field and str(field[0]).lower() in ('1', 'true', 'yes', 'on'):
            raise ValueError('Finish field work mode before maintenance')
except Exception as error:
    print('ERROR: ' + (str(error) if isinstance(error, ValueError) else 'Cannot verify maintenance readiness'), file=sys.stderr)
    sys.exit(1)
PY_ADMISSION_CHECK
}

sqlite_database_tool() {
    # Stdlib only, so this also works before the application/venv is upgraded.
    python3 -I - "$@" << 'PY_SQLITE_TOOL'
from contextlib import closing
import os
from pathlib import Path
import sqlite3
import stat
import sys
import tempfile
import time


def sqlite_database_tool(mode, source_path, destination_path=None):
    if mode not in ('check', 'snapshot', 'restore'):
        raise ValueError('Unknown database operation')
    source = Path(source_path).resolve(strict=True)
    with closing(sqlite3.connect(source.as_uri() + '?mode=ro', uri=True, timeout=1)) as reader:
        if mode == 'check':
            if reader.execute('PRAGMA integrity_check').fetchall() != [('ok',)]:
                raise ValueError('SQLite integrity check failed')
            return
        destination = Path(destination_path).absolute()
        if destination.is_symlink() or destination.resolve() == source:
            raise ValueError('Database destination must be a separate regular path')
        deadline = time.monotonic() + 30
        def progress(status, remaining, total):
            if time.monotonic() >= deadline:
                raise TimeoutError('SQLite snapshot exceeded 30 seconds')
        descriptor, temporary_name = tempfile.mkstemp(prefix='.gnss-db-', dir=destination.parent)
        os.close(descriptor)
        temporary = Path(temporary_name)
        try:
            with closing(sqlite3.connect(temporary, timeout=1)) as writer:
                reader.backup(writer, pages=256, progress=progress, sleep=0.05)
                # The result must be independently usable without any sidecar.
                writer.execute('PRAGMA journal_mode=DELETE')
                if writer.execute('PRAGMA integrity_check').fetchall() != [('ok',)]:
                    raise ValueError('SQLite snapshot integrity check failed')
            source_stat = source.stat()
            with temporary.open('r+b') as handle:
                os.fsync(handle.fileno())
            os.chmod(temporary, stat.S_IMODE(source_stat.st_mode))
            if os.name == 'posix':
                os.chown(temporary, source_stat.st_uid, source_stat.st_gid)
            if mode == 'restore':
                # Caller MUST have stopped all writers and hold the maintenance
                # lock. Never attach old WAL/journal files to the restored DB.
                for suffix in ('-shm', '-journal', '-wal'):
                    Path(str(destination) + suffix).unlink(missing_ok=True)
            os.replace(temporary, destination)
            if os.name == 'posix':
                directory_fd = os.open(destination.parent, os.O_RDONLY | os.O_DIRECTORY)
                try:
                    os.fsync(directory_fd)
                finally:
                    os.close(directory_fd)
        finally:
            for suffix in ('', '-wal', '-shm', '-journal'):
                Path(str(temporary) + suffix).unlink(missing_ok=True)


if __name__ == '__main__':
    try:
        sqlite_database_tool(*sys.argv[1:])
    except Exception as exc:
        print(f'ERROR: SQLite operation failed: {exc}', file=sys.stderr)
        sys.exit(1)
PY_SQLITE_TOOL
}

# BEGIN GENERATED RECOVERY JOURNAL
write_recovery_support() {
    local recovery_store="/var/lib/gnss-caster-maintenance"
    local recovery_temp
    if [ -L "$recovery_store" ] || { [ -e "$recovery_store" ] && {
        [ ! -d "$recovery_store" ] || [ "$(stat -c %u "$recovery_store")" != 0 ] ||
        [ "$(stat -c %a "$recovery_store")" != 700 ]; }; }; then
        echo "ERROR: Unsafe recovery storage" >&2
        return 1
    fi
    install -d -o root -g root -m 700 "$recovery_store" || return 1
    recovery_temp=$(mktemp "$recovery_store/.recovery-XXXXXX") || return 1
    cat > "$recovery_temp" << 'PYTHON_RECOVERY_JOURNAL' || return 1
"""Durable repair journal and explicit local recovery. Stdlib, root-only.

Snapshots and this program live outside the application account's writable
directories. Nothing is recovered automatically after an unclean shutdown.
"""
import contextlib
import hashlib
import json
import os
from pathlib import Path
import re
import sqlite3
import stat
import subprocess
import sys
import tempfile
import time

ROOT = Path('/var/backups/gnss-caster')
BASE = Path('/opt/gnss-caster')
MAINTENANCE_LOCK = Path('/run/gnss-caster-maintenance.lock')
ADMISSION_LOCK = Path('/var/lib/gnss-caster-admission.lock')
TERMINAL = {'committed', 'rolled_back', 'snapshot_failed'}
PHASES = {'snapshotting', 'prepared', 'dependencies', 'configuration', 'migration',
          'health', 'rollback', 'recovery', 'resuming', 'rollback_failed'} | TERMINAL
ENV = {'PATH': '/usr/sbin:/usr/bin:/sbin:/bin', 'LANG': 'C.UTF-8', 'HOME': '/root'}


class RecoveryError(Exception):
    pass


def trusted_directory(path):
    info = path.lstat()
    if not stat.S_ISDIR(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o077:
        raise RecoveryError('Recovery directory must be private and root-owned')


def trusted_file(path):
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1 or info.st_mode & 0o022:
        raise RecoveryError('Unsafe recovery metadata')


def snapshot_path(value):
    path = Path(value)
    if not path.is_absolute():
        path = ROOT / path
    if path.parent != ROOT or not re.fullmatch(r'rollback-[A-Za-z0-9_-]{1,100}', path.name):
        raise RecoveryError('Expected a snapshot ID in the rollback directory')
    trusted_directory(ROOT)
    trusted_directory(path)
    return path


def fsync_directory(path):
    if os.name == 'posix':
        fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)


def write_json(path, data):
    fd, temporary = tempfile.mkstemp(prefix='.journal-', dir=path.parent)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as stream:
            json.dump(data, stream, ensure_ascii=True, sort_keys=True)
            stream.flush()
            os.fsync(stream.fileno())
        os.replace(temporary, path)
        fsync_directory(path.parent)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


def read_state(path):
    trusted_file(path / 'transaction.json')
    data = json.loads((path / 'transaction.json').read_text(encoding='utf-8'))
    if (data.get('format') != 1 or data.get('id') != path.name
            or data.get('phase') not in PHASES or type(data.get('snapshot_ready')) is not bool):
        raise RecoveryError('Unsupported or invalid recovery journal')
    return data


def boot_id():
    return Path('/proc/sys/kernel/random/boot_id').read_text().strip()


def process_identity(pid):
    # comm can contain spaces and parentheses. starttime is field 22.
    return Path(f'/proc/{int(pid)}/stat').read_text().rsplit(')', 1)[1].split()[19]


def set_owner(data, pid):
    data.update(owner_pid=int(pid), owner_start=process_identity(pid), boot_id=boot_id())


def save(path, data, phase):
    if phase not in PHASES:
        raise RecoveryError('Unknown maintenance phase')
    data.update(phase=phase, updated_at=int(time.time()))
    write_json(path / 'transaction.json', data)


def begin(path, mode, target, pid):
    if (path / 'transaction.json').exists():
        raise RecoveryError('Snapshot already has a transaction journal')
    trusted_file(path / 'recover.sh')
    trusted_file(path / 'service-state.json')
    services = json.loads((path / 'service-state.json').read_text(encoding='utf-8'))
    previous = 'unknown'
    try:
        source = (BASE / 'app/version.py').read_text(encoding='utf-8')
        match = re.search(r'^__version__ = [\'"]([0-9.]+)[\'"]$', source, re.M)
        if match:
            previous = match[1]
    except OSError:
        pass
    # Persist the service-only recovery program before stopping any writer.
    evidence = inventory(path, names=('recover.sh', 'service-state.json', 'paths.list'), durable=True)
    data = {'format': 1, 'id': path.name, 'mode': mode, 'previous_version': previous,
            'target_version': target, 'created_at': int(time.time()), 'services': services,
            'snapshot_ready': False, 'initial_inventory': evidence}
    set_owner(data, pid)
    save(path, data, 'snapshotting')
    # The directory entry itself must survive power loss as well as its files.
    fsync_directory(ROOT)
    fsync_directory(ROOT.parent)


def inventory(path, names=('files', 'recover.sh', 'service-state.json', 'paths.list',
                           'existed.list', 'missing.list'), durable=False):
    result = {}

    def visit(item):
        info = item.lstat()
        record = {'mode': stat.S_IMODE(info.st_mode), 'uid': info.st_uid, 'gid': info.st_gid}
        if stat.S_ISLNK(info.st_mode):
            record.update(kind='link', target=os.readlink(item))
        elif stat.S_ISDIR(info.st_mode):
            record['kind'] = 'directory'
            for child in sorted(item.iterdir()):
                visit(child)
            if durable:
                fsync_directory(item)
        elif stat.S_ISREG(info.st_mode):
            digest = hashlib.sha256()
            with item.open('rb') as stream:
                for chunk in iter(lambda: stream.read(1024 * 1024), b''):
                    digest.update(chunk)
                if durable and os.name == 'posix':
                    os.fsync(stream.fileno())
            record.update(kind='file', size=info.st_size, sha256=digest.hexdigest())
        else:
            raise RecoveryError('Snapshot contains an unsupported filesystem object')
        result[str(item.relative_to(path))] = record

    for name in names:
        visit(path / name)
    if durable:
        fsync_directory(path)
    return result


def ready(path):
    data = read_state(path)
    if data['phase'] != 'snapshotting' or data['snapshot_ready']:
        raise RecoveryError('Snapshot cannot be prepared from this state')
    data['inventory'] = inventory(path, durable=True)
    data['snapshot_ready'] = True
    save(path, data, 'prepared')


def mark(path, phase):
    data = read_state(path)
    if phase not in TERMINAL:
        set_owner(data, os.getppid())
    save(path, data, phase)


def list_states():
    if not ROOT.exists():
        return []
    trusted_directory(ROOT)
    result = []
    for path in sorted(ROOT.glob('rollback-*')):
        # Older snapshots have no journal and are deliberately not guessed.
        if not (path / 'transaction.json').exists():
            continue
        path = snapshot_path(path)
        result.append((path, read_state(path)))
    return result


def owner_alive(data):
    try:
        return (data['boot_id'] == boot_id()
                and data['owner_start'] == process_identity(data['owner_pid']))
    except (OSError, KeyError, ValueError, IndexError):
        return False


def pending():
    return [(path, data) for path, data in list_states() if data['phase'] not in TERMINAL]


@contextlib.contextmanager
def exclusive(path, create=False):
    import fcntl
    fd = os.open(path, os.O_RDWR | os.O_NOFOLLOW | (os.O_CREAT if create else 0), 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1:
            raise RecoveryError('Unsafe maintenance lock')
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as error:
            raise RecoveryError('Another maintenance operation or rover admission is running') from error
        yield fd
    finally:
        os.close(fd)


def preflight():
    unfinished = pending()
    if unfinished:
        raise RecoveryError('Unfinished maintenance requires local recovery: ' + ', '.join(path.name for path, _ in unfinished))


def boot_check():
    unfinished = pending()
    if not unfinished:
        return
    # A current, identifiable installer may start the service for its health
    # gate. An old PID, a new boot or a lost lock never authorizes startup.
    if all(data['phase'] in ('health', 'resuming') and owner_alive(data) for _, data in unfinished):
        try:
            with exclusive(MAINTENANCE_LOCK, create=True):
                pass
        except RecoveryError as error:
            if str(error) == 'Another maintenance operation or rover admission is running':
                return
            raise
    raise RecoveryError('Caster startup blocked by unfinished maintenance. Run recovery.py status, then recover the indicated snapshot.')


def verify(path, data):
    if data['snapshot_ready']:
        actual = inventory(path)
        expected = data.get('inventory')
    else:
        if data['phase'] not in ('snapshotting', 'recovery', 'resuming', 'rollback_failed'):
            raise RecoveryError('Incomplete snapshot cannot restore application files')
        actual = inventory(path, names=('recover.sh', 'service-state.json', 'paths.list'))
        expected = data.get('initial_inventory')
    if actual != expected:
        raise RecoveryError('Snapshot contents differ from the durable manifest; no recovery was started')


def run(arguments, **kwargs):
    return subprocess.run(arguments, env=ENV, text=True, **kwargs)


def check_live_work():
    result = run(['/usr/bin/systemctl', 'show', 'gnss-caster', '--property=ActiveState', '--value'],
                 capture_output=True, timeout=15)
    state = result.stdout.strip()
    if result.returncode or state not in ('active', 'inactive', 'failed'):
        raise RecoveryError('Cannot establish whether caster is stopped')
    if state in ('inactive', 'failed'):
        return  # Explicit local recovery is allowed even with a broken DB.
    database = BASE / 'instance/db.sqlite'
    config = (BASE / 'instance/config.yaml').read_text(encoding='utf-8')
    configured = re.findall(r'^\s+path:\s*[\'"]?([^\s\'"#]+)[\'"]?\s*(?:#.*)?$', config, re.M)
    if configured != [str(database)]:
        raise RecoveryError('Recovery of a running caster requires the standard database location')
    with contextlib.closing(sqlite3.connect(database.as_uri() + '?mode=ro', uri=True, timeout=5)) as db:
        field = db.execute("SELECT value FROM system_setting WHERE key='field_work_active'").fetchone()
        if field and str(field[0]).strip().lower() in ('1', 'true', 'yes', 'on'):
            raise RecoveryError('Finish field work mode before recovery')
        if db.execute('SELECT COALESCE(SUM(active_conn), 0) FROM rover').fetchone()[0]:
            raise RecoveryError('Disconnect all rovers before recovery')


def recover(path):
    with exclusive(MAINTENANCE_LOCK, create=True) as maintenance_fd, exclusive(ADMISSION_LOCK) as admission_fd:
        data = read_state(path)
        if data['phase'] in TERMINAL:
            raise RecoveryError('Transaction is already complete; this command only recovers unfinished work')
        others = [item.name for item, _ in pending() if item != path]
        if others:
            raise RecoveryError('More than one unfinished transaction requires manual inspection')
        verify(path, data)
        check_live_work()
        set_owner(data, os.getpid())
        save(path, data, 'recovery')
        try:
            # This root-owned, hashed program contains the exact rollback
            # functions and original service settings captured before mutation.
            result = run(['/bin/bash', '--noprofile', '--norc', str(path / 'recover.sh'),
                          '--restore' if data['snapshot_ready'] else '--services-only'],
                         pass_fds=(maintenance_fd, admission_fd))
            if result.returncode:
                raise RecoveryError('Recovery failed; inspect the retained snapshot and service logs')
        except BaseException:
            save(path, data, 'rollback_failed')
            raise
        save(path, data, 'rolled_back' if data['snapshot_ready'] else 'snapshot_failed')
        return data


def summary(path, data):
    return {**{key: value for key, value in data.items()
               if key not in ('inventory', 'initial_inventory', 'owner_start')},
            'snapshot': str(path),
            'recovery_command': f'sudo python3 -I /var/lib/gnss-caster-maintenance/recovery.py recover {path.name} --confirm'}


def main(arguments):
    if os.geteuid() != 0:
        raise RecoveryError('Run this recovery command as root')
    if arguments == ['status']:
        print(json.dumps([summary(path, data) for path, data in list_states()], ensure_ascii=True, indent=2))
    elif arguments == ['preflight']:
        preflight()
    elif arguments == ['boot-check']:
        boot_check()
    elif len(arguments) == 3 and arguments[0] == 'recover' and arguments[2] == '--confirm':
        path = snapshot_path(arguments[1])
        print(json.dumps(summary(path, recover(path)), ensure_ascii=True))
    elif len(arguments) == 5 and arguments[0] == 'begin':
        begin(snapshot_path(arguments[1]), arguments[2], arguments[3], int(arguments[4]))
    elif len(arguments) == 2 and arguments[0] == 'ready':
        ready(snapshot_path(arguments[1]))
    elif len(arguments) == 3 and arguments[0] == 'mark':
        mark(snapshot_path(arguments[1]), arguments[2])
    else:
        raise RecoveryError('Usage: recovery.py status | recover SNAPSHOT_ID --confirm')


if __name__ == '__main__':
    try:
        main(sys.argv[1:])
    except (RecoveryError, OSError, ValueError, sqlite3.Error) as error:
        print('ERROR: ' + str(error), file=sys.stderr)
        sys.exit(1)

PYTHON_RECOVERY_JOURNAL
    chown root:root "$recovery_temp" || return 1
    chmod 700 "$recovery_temp" || return 1
    mv -f "$recovery_temp" "$recovery_store/recovery.py" || return 1
    sync -f "$recovery_store"
}
# END GENERATED RECOVERY JOURNAL

rollback_backup_path() {
    local source_path="$1"
    printf '%s/files%s\n' "$ROLLBACK_DIR" "$source_path"
}

backup_path_for_rollback() {
    local source_path="$1"
    local dest_path

    if [ -z "$ROLLBACK_DIR" ]; then
        return 0
    fi

    dest_path=$(rollback_backup_path "$source_path")
    mkdir -p "$(dirname "$dest_path")"

    if [ -e "$source_path" ] || [ -L "$source_path" ]; then
        # A rollback snapshot is only useful if it is complete. Never record an
        # object as backed up after a failed copy: doing so could make rollback
        # delete the live object and replace it with a partial snapshot.
        if { [ "$source_path" = "$INST/db.sqlite" ] &&
                sqlite_database_tool snapshot "$source_path" "$dest_path"; } ||
           { [ "$source_path" != "$INST/db.sqlite" ] && cp -a "$source_path" "$dest_path"; }; then
            printf '%s\n' "$source_path" >> "$ROLLBACK_DIR/existed.list"
        else
            echo "ERROR: Failed to snapshot $source_path for rollback" >&2
            rm -rf "$dest_path" 2>/dev/null || true
            return 1
        fi
    else
        printf '%s\n' "$source_path" >> "$ROLLBACK_DIR/missing.list"
    fi
}

print_install_rollback_paths() {
    printf '%s\n' \
        "$SERVICE" \
        "/etc/systemd/system/gnss-caster.service.d" \
        "$NGINX_AVAILABLE" \
        "$NGINX_ENABLED" \
        "/etc/nginx/sites-enabled/default" \
        "$NGINX_SECURITY_CONF" \
        "$FAIL2BAN_FILTER" \
        "$FAIL2BAN_JAIL" \
        "$UFW_APP_PROFILE" \
        "$MAINTENANCE_CRON" \
        "$BACKUP_CRON" \
        "/etc/cron.d/gnss-caster-cert-renew" \
        "/etc/logrotate.d/gnss-caster" \
        "$SUDOERS_FILE" \
        "$POLKIT_RULE" \
        "$PRIVILEGED_HELPER" \
        "$BASE/main.py" \
        "$BASE/requirements.txt" \
        "$BASE/sqlite-functions.sh" \
        "$BASE/backup.sh" \
        "$BASE/restore.sh" \
        "$BASE/monitor.sh" \
        "$BASE/watchdog.sh" \
        "$BASE/update.sh" \
        "$BASE/release-update.py" \
        "$BASE/diagnose.sh" \
        "$BASE/status.sh" \
        "$BASE/repair.sh" \
        "$BASE/gnss-caster-installer.sh" \
        "$APP" \
        "$VENV" \
        "$INST/config.yaml" \
        "$INST/config.py" \
        "$INST/db.sqlite" \
        "$OLD_BOOTSTRAP_ADMIN_PASSWORD_FILE" \
        "$BOOTSTRAP_ADMIN_PASSWORD_FILE" \
        "$SECRET_DIR" \
        "$LEGACY_SECRET_KEY_ENV_FILE" \
        "$SELF_SIGNED_CERT" \
        "$SELF_SIGNED_KEY"
    local legacy_backup
    for legacy_backup in "$INST"/secret.env.bak-*; do
        [ -e "$legacy_backup" ] || [ -L "$legacy_backup" ] || continue
        printf '%s\n' "$legacy_backup"
    done
    if [ "$SCRIPT_MODE" = repair ]; then
        printf '%s\n' /etc/ufw/user.rules /etc/ufw/user6.rules
    fi
}

record_install_journal() {
    [ -n "$ROLLBACK_DIR" ] && [ -f "$ROLLBACK_DIR/transaction.json" ] || return 0
    python3 -I /var/lib/gnss-caster-maintenance/recovery.py mark "$ROLLBACK_DIR" "$1"
}

record_maintenance_phase() {
    echo "GNSS maintenance stage: $1"
    record_install_journal "$1"
}

prepare_install_recovery() {
    # The saved program is root-only and hashed before the service is stopped.
    # Freeze the allowlist rather than recomputing it from partly changed files.
    (umask 077
        print_install_rollback_paths > "$ROLLBACK_DIR/paths.list" || exit 1
        {
            printf '%s\n' '#!/bin/bash' 'set -eE'
            declare -p SCRIPT_MODE ROLLBACK_DIR INST SERVICE \
                INSTALL_CASTER_WAS_ACTIVE INSTALL_NGINX_WAS_ACTIVE \
                INSTALL_CASTER_ENABLED INSTALL_HEALTH_WAS_OK INSTALL_HEALTH_URL || exit 1
            printf 'REPAIR_UFW_WAS_ACTIVE=%s\n' "${REPAIR_UFW_WAS_ACTIVE:-0}"
            printf '%s\n' 'ROLLBACK_ACTIVE=1'
            declare -f sqlite_database_tool rollback_backup_path \
                record_install_journal record_maintenance_phase \
                restore_install_service_state validate_install_rollback_snapshot \
                restore_install_rollback_snapshot || exit 1
            printf '%s\n' 'print_install_rollback_paths() { cat "$ROLLBACK_DIR/paths.list"; }'
            printf '%s\n' 'case "${1:-}" in' \
                '  --restore) restore_install_rollback_snapshot;;' \
                '  --services-only) restore_install_service_state;;' \
                '  *) exit 2;;' 'esac'
        } > "$ROLLBACK_DIR/recover.sh" || exit 1
        python3 -I - "$ROLLBACK_DIR/service-state.json" "$INSTALL_CASTER_WAS_ACTIVE" \
            "$INSTALL_NGINX_WAS_ACTIVE" "$INSTALL_CASTER_ENABLED" \
            "$INSTALL_HEALTH_WAS_OK" "$INSTALL_HEALTH_URL" "${REPAIR_UFW_WAS_ACTIVE:-0}" << 'PY_RECOVERY_SERVICES'
import json
import sys
from pathlib import Path
keys = ('caster_active', 'nginx_active', 'caster_enabled', 'health_was_ok', 'health_url', 'ufw_active')
Path(sys.argv[1]).write_text(json.dumps(dict(zip(keys, sys.argv[2:]))), encoding='utf-8')
PY_RECOVERY_SERVICES
    ) || return 1
    bash -n "$ROLLBACK_DIR/recover.sh" || return 1
    python3 -I /var/lib/gnss-caster-maintenance/recovery.py begin \
        "$ROLLBACK_DIR" "$SCRIPT_MODE" "$CASTER_VERSION" "$BASHPID"
}

create_install_rollback_snapshot() {
    local ts
    local path
    local existing_state_found=0

    systemctl is-active --quiet gnss-caster && INSTALL_CASTER_WAS_ACTIVE=1 || INSTALL_CASTER_WAS_ACTIVE=0
    systemctl is-active --quiet nginx && INSTALL_NGINX_WAS_ACTIVE=1 || INSTALL_NGINX_WAS_ACTIVE=0
    INSTALL_CASTER_ENABLED=$(systemctl is-enabled gnss-caster 2>/dev/null || true)
    INSTALL_CASTER_ENABLED="${INSTALL_CASTER_ENABLED:-not-found}"
    INSTALL_STATE_CAPTURED=1
    if [ "$INSTALL_CASTER_WAS_ACTIVE" -eq 1 ]; then
        INSTALL_HEALTH_URL="http://127.0.0.1:$(get_config_value web_port 8080)/api/health"
        curl -fsS --max-time 3 "$INSTALL_HEALTH_URL" >/dev/null 2>&1 && INSTALL_HEALTH_WAS_OK=1 || INSTALL_HEALTH_WAS_OK=0
    fi

    # Treat installation as "existing" only when core runtime/config artifacts
    # are present. An empty /opt/gnss-caster directory alone should not trigger
    # rollback snapshot creation during a clean install.
    for path in \
        "$SERVICE" \
        "$NGINX_AVAILABLE" \
        "$APP" \
        "$VENV" \
        "$INST/config.yaml" \
        "$INST/db.sqlite" \
        "$PRIVILEGED_HELPER" \
        "$SUDOERS_FILE" \
        "$POLKIT_RULE"; do
        if [ -e "$path" ] || [ -L "$path" ]; then
            existing_state_found=1
            break
        fi
    done

    if [ "$existing_state_found" -ne 1 ]; then
        # Even a clean installation must not copy files while a stray service runs.
        systemctl stop gnss-caster 2>/dev/null || true
        if systemctl is-active --quiet gnss-caster; then return 1; fi
        ROLLBACK_DIR=""
        ROLLBACK_ACTIVE=0
        echo "Clean install detected; no existing GNSS Caster state to snapshot."
        return 0
    fi

    ts=$(date +%Y%m%d_%H%M%S)
    mkdir -p "$ROLLBACK_ROOT" || return 1
    chown root:root "$ROLLBACK_ROOT" || return 1
    chmod 700 "$ROLLBACK_ROOT" || return 1
    ROLLBACK_DIR=$(mktemp -d "$ROLLBACK_ROOT/rollback-$ts-XXXXXX") || return 1
    : > "$ROLLBACK_DIR/existed.list"
    : > "$ROLLBACK_DIR/missing.list"
    mkdir -p "$ROLLBACK_DIR/files"
    prepare_install_recovery || return 1

    # Persist original service state before stopping a writer. During this
    # phase recovery only resumes services: live files have not been changed.
    if [ "$INSTALL_CASTER_WAS_ACTIVE" -eq 1 ]; then
        systemctl stop gnss-caster || return 1
    fi
    if systemctl is-active --quiet gnss-caster; then
        echo "ERROR: GNSS Caster is still running; refusing to snapshot." >&2
        return 1
    fi

    while IFS= read -r path; do
        [ -n "$path" ] || continue
        backup_path_for_rollback "$path" || return 1
    done << EOF
$(print_install_rollback_paths)
EOF

    python3 -I /var/lib/gnss-caster-maintenance/recovery.py ready "$ROLLBACK_DIR" || return 1
    ROLLBACK_ACTIVE=1
    echo "Rollback snapshot created: $ROLLBACK_DIR"
}

restore_install_service_state() {
    local failed=0
    local attempt
    record_install_journal resuming || return 1
    # Repair updates UFW application rules as well as its profile file.
    if [ "$SCRIPT_MODE" = repair ] && [ "${REPAIR_UFW_WAS_ACTIVE:-0}" -eq 1 ]; then
        ufw reload || return 1
    fi
    case "$INSTALL_CASTER_ENABLED" in
        enabled) systemctl enable gnss-caster >/dev/null 2>&1 || failed=1 ;;
        enabled-runtime) systemctl enable --runtime gnss-caster >/dev/null 2>&1 || failed=1 ;;
        disabled|not-found)
            if [ -f "$SERVICE" ]; then
                systemctl disable gnss-caster >/dev/null 2>&1 || failed=1
            fi
            ;;
    esac
    if [ "$INSTALL_NGINX_WAS_ACTIVE" -eq 1 ]; then
        if nginx -t; then
            if systemctl is-active --quiet nginx; then
                systemctl reload nginx || failed=1
            else
                systemctl start nginx || failed=1
            fi
        else
            failed=1
        fi
    elif systemctl is-active --quiet nginx; then
        systemctl stop nginx || failed=1
    fi
    if [ "$INSTALL_CASTER_WAS_ACTIVE" -eq 1 ]; then
        systemctl start gnss-caster || return 1
        systemctl is-active --quiet gnss-caster || return 1
        if [ "$INSTALL_HEALTH_WAS_OK" -eq 1 ]; then
            for attempt in {1..10}; do
                if curl -fsS --max-time 3 "$INSTALL_HEALTH_URL" >/dev/null 2>&1; then
                    return "$failed"
                fi
                sleep 1
            done
            echo "ERROR: Restored caster did not recover its previous web health." >&2
            return 1
        fi
    elif systemctl is-active --quiet gnss-caster; then
        systemctl stop gnss-caster || failed=1
    fi
    return "$failed"
}

validate_install_rollback_snapshot() {
    local source_path backup_path expected_path allowed
    [ -f "$ROLLBACK_DIR/existed.list" ] && [ -f "$ROLLBACK_DIR/missing.list" ] || return 1
    while IFS= read -r source_path; do
        allowed=0
        while IFS= read -r expected_path; do
            [ "$source_path" = "$expected_path" ] && allowed=1
        done < <(print_install_rollback_paths)
        [ "$allowed" -eq 1 ] || return 1
    done < <(cat "$ROLLBACK_DIR/existed.list" "$ROLLBACK_DIR/missing.list")
    while IFS= read -r source_path; do
        if grep -Fxq -- "$source_path" "$ROLLBACK_DIR/existed.list"; then
            if grep -Fxq -- "$source_path" "$ROLLBACK_DIR/missing.list"; then return 1; fi
            backup_path=$(rollback_backup_path "$source_path")
            [ -e "$backup_path" ] || [ -L "$backup_path" ] || return 1
            if [ "$source_path" = "$INST/db.sqlite" ]; then
                sqlite_database_tool check "$backup_path" || return 1
            fi
        else
            grep -Fxq -- "$source_path" "$ROLLBACK_DIR/missing.list" || return 1
        fi
    done < <(print_install_rollback_paths)
}

restore_install_rollback_snapshot() {
    record_maintenance_phase rollback
    local source_path backup_path
    local failed=0
    [ "$ROLLBACK_ACTIVE" -eq 1 ] && [ -d "$ROLLBACK_DIR" ] || return 1
    if ! systemctl stop gnss-caster; then
        if systemctl is-active --quiet gnss-caster; then return 1; fi
    fi
    if systemctl is-active --quiet gnss-caster; then return 1; fi
    # Validate every snapshot component before deleting any live file.
    if ! validate_install_rollback_snapshot; then
        echo "ERROR: Rollback snapshot is incomplete or invalid: $ROLLBACK_DIR" >&2
        return 1
    fi
    echo "Restoring GNSS Caster from $ROLLBACK_DIR"
    while IFS= read -r source_path; do
        if [ "$source_path" = "$INST/db.sqlite" ]; then
            rm -f -- "$source_path-wal" "$source_path-shm" "$source_path-journal" || failed=1
        fi
        rm -rf -- "$source_path" || failed=1
    done < "$ROLLBACK_DIR/missing.list"
    while IFS= read -r source_path; do
        backup_path=$(rollback_backup_path "$source_path")
        if ! mkdir -p "$(dirname "$source_path")"; then failed=1; continue; fi
        if [ "$source_path" = "$INST/db.sqlite" ]; then
            sqlite_database_tool restore "$backup_path" "$source_path" || failed=1
        elif rm -rf -- "$source_path"; then
            cp -a "$backup_path" "$source_path" || failed=1
        else
            failed=1
        fi
    done < "$ROLLBACK_DIR/existed.list"
    if [ "$failed" -ne 0 ]; then
        echo "ERROR: File rollback was incomplete; caster remains stopped. Snapshot: $ROLLBACK_DIR" >&2
        return 1
    fi
    systemctl daemon-reload || return 1
    restore_install_service_state || return 1
    ROLLBACK_ACTIVE=0
    record_install_journal rolled_back || return 1
    echo "Rollback completed; previous service state restored."
}

handle_install_exit() {
    local exit_code=$?
    # ERR is inherited by command substitutions; only the main shell restores.
    [ "$BASHPID" = "$INSTALL_OWNER_BASHPID" ] || return "$exit_code"
    trap - EXIT ERR
    trap '' INT TERM HUP
    set +e
    if { [ "$SCRIPT_MODE" = "install" ] || [ "$SCRIPT_MODE" = "repair" ]; } && [ "$INSTALL_COMMITTED" -ne 1 ] && [ "$INSTALL_STATE_CAPTURED" -eq 1 ]; then
        [ "$exit_code" -ne 0 ] || exit_code=1
        echo "ERROR: $SCRIPT_MODE did not complete (near line $INSTALL_FAILED_LINE)."
        if [ "$ROLLBACK_ACTIVE" -eq 1 ]; then
            if ! restore_install_rollback_snapshot; then
                record_install_journal rollback_failed || true
                echo "ERROR: Automatic rollback failed. Inspect snapshot: $ROLLBACK_DIR" >&2
            fi
        else
            # No installation files have been changed during a failed snapshot.
            # On a clean install, there is no previous runtime to restore.
            if ! restore_install_service_state; then
                record_install_journal rollback_failed || true
                echo "ERROR: Could not restore the previous service state." >&2
            else
                record_install_journal snapshot_failed || true
            fi
        fi
        [ -z "$ROLLBACK_DIR" ] || echo "Snapshot retained: $ROLLBACK_DIR"
    fi
    exit "$exit_code"
}

begin_runtime_transaction() {
    acquire_admission_guard || return 1
    write_recovery_support || return 1
    python3 -I /var/lib/gnss-caster-maintenance/recovery.py preflight || return 1
    echo "GNSS maintenance stage: snapshot"
    if [ "$SCRIPT_MODE" = repair ] && command -v ufw >/dev/null 2>&1; then
        local firewall_status
        firewall_status=$(ufw status) || return 1
        REPAIR_UFW_WAS_ACTIVE=0
        if printf '%s\n' "$firewall_status" | grep -qi '^Status: active'; then
            REPAIR_UFW_WAS_ACTIVE=1
        fi
    fi
    INSTALL_OWNER_BASHPID=$BASHPID
    trap handle_install_exit EXIT
    trap 'INSTALL_FAILED_LINE=$LINENO' ERR
    trap 'INSTALL_FAILED_LINE=$LINENO; exit 130' INT
    trap 'INSTALL_FAILED_LINE=$LINENO; exit 143' TERM
    trap 'INSTALL_FAILED_LINE=$LINENO; exit 129' HUP
    create_install_rollback_snapshot
}

finish_repair_transaction() {
    record_maintenance_phase health
    if ! run_install_smoke_tests; then
        echo "ERROR: Post-repair health gate failed; rolling back." >&2
        return 1
    fi
    # Repair temporarily starts the service to validate it, then preserves
    # the original activity and enablement settings (including nginx).
    restore_install_service_state || return 1
    record_install_journal committed || return 1
    INSTALL_COMMITTED=1
    ROLLBACK_ACTIVE=0
    trap - ERR INT TERM HUP
    # Legacy secret cleanup must follow commit: deleting these paths earlier
    # would change the manifest used by snapshot validation.
    manage_secret_files cleanup
}

validate_tls_config() {
    case "$TLS_MODE" in
        none|selfsigned|letsencrypt|existing)
            ;;
        *)
            echo "ERROR: Unsupported TLS_MODE='$TLS_MODE'"
            echo "Use one of: none, selfsigned, letsencrypt, existing"
            exit 1
            ;;
    esac

    if [ "$TLS_MODE" = "letsencrypt" ]; then
        if [ -z "$TLS_DOMAIN" ] || [ -z "$TLS_EMAIL" ]; then
            echo "ERROR: TLS_MODE=letsencrypt requires TLS_DOMAIN and TLS_EMAIL"
            echo "Example:"
            echo "  TLS_MODE=letsencrypt TLS_DOMAIN=example.com TLS_EMAIL=admin@example.com ./$SCRIPT_NAME"
            exit 1
        fi
        if ! [[ "$TLS_EMAIL" =~ ^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$ ]]; then
            echo "ERROR: TLS_EMAIL '$TLS_EMAIL' is not a valid email address."
            exit 1
        fi
    fi

    if [ "$TLS_MODE" = "existing" ]; then
        if [ -z "$TLS_CERT_FILE" ] || [ -z "$TLS_KEY_FILE" ]; then
            echo "ERROR: TLS_MODE=existing requires TLS_CERT_FILE and TLS_KEY_FILE"
            echo "Example:"
            echo "  TLS_MODE=existing TLS_CERT_FILE=/etc/ssl/mycert/fullchain.pem TLS_KEY_FILE=/etc/ssl/mycert/privkey.pem ./$SCRIPT_NAME"
            exit 1
        fi
        if [ ! -r "$TLS_CERT_FILE" ]; then
            echo "ERROR: certificate file not found or not readable: $TLS_CERT_FILE"
            exit 1
        fi
        if [ ! -r "$TLS_KEY_FILE" ]; then
            echo "ERROR: private key file not found or not readable: $TLS_KEY_FILE"
            exit 1
        fi
        if ! openssl x509 -in "$TLS_CERT_FILE" -noout >/dev/null 2>&1; then
            echo "ERROR: $TLS_CERT_FILE is not a valid PEM X.509 certificate"
            exit 1
        fi
        if ! openssl pkey -in "$TLS_KEY_FILE" -noout >/dev/null 2>&1; then
            echo "ERROR: $TLS_KEY_FILE is not a valid PEM private key"
            exit 1
        fi
        # Confirm the key actually matches the certificate by comparing public
        # keys (works for both RSA and EC, unlike a modulus-only check).
        local _cert_pub _key_pub
        _cert_pub=$(openssl x509 -in "$TLS_CERT_FILE" -noout -pubkey 2>/dev/null)
        _key_pub=$(openssl pkey -in "$TLS_KEY_FILE" -pubout 2>/dev/null)
        if [ -z "$_cert_pub" ] || [ "$_cert_pub" != "$_key_pub" ]; then
            echo "ERROR: the private key does not match the certificate"
            echo "  cert: $TLS_CERT_FILE"
            echo "  key : $TLS_KEY_FILE"
            exit 1
        fi
        # Non-fatal expiry warning: nginx will still start, but clients will
        # reject an expired certificate.
        if ! openssl x509 -in "$TLS_CERT_FILE" -checkend 0 >/dev/null 2>&1; then
            echo "WARNING: certificate $TLS_CERT_FILE is expired or unreadable dates; proceeding anyway."
        fi
    fi

    if [ -n "$TLS_DOMAIN" ]; then
        # TLS_DOMAIN reaches nginx "server_name", the certbot "-d" argument, the
        # self-signed cert CN, and the /etc/letsencrypt/live/<domain> path.
        # Restrict it to hostname characters so a crafted value cannot inject
        # nginx directives (";", newlines, "{}"), certbot flags (leading "-"),
        # extra subject-DN fields ("/"), or traverse paths.
        if ! [[ "$TLS_DOMAIN" =~ ^[A-Za-z0-9]([A-Za-z0-9.-]{0,253})$ ]]; then
            echo "ERROR: TLS_DOMAIN '$TLS_DOMAIN' is not a valid hostname."
            echo "Use letters, digits, dots and hyphens only, starting with a letter or digit (e.g. caster.example.com)."
            exit 1
        fi
        NGINX_SERVER_NAME="$TLS_DOMAIN"
    fi
}

validate_tcp_port() {
    local port_label="$1"
    local port_value="$2"

    case "$port_value" in
        ''|*[!0-9]*)
            echo "ERROR: $port_label must be a numeric TCP port, got '$port_value'"
            exit 1
            ;;
    esac

    if [ "$port_value" -lt 1 ] || [ "$port_value" -gt 65535 ]; then
        echo "ERROR: $port_label must be between 1 and 65535, got '$port_value'"
        exit 1
    fi
}

validate_install_ports() {
    validate_tcp_port "WEB_PORT" "$INSTALL_WEB_PORT"
    validate_tcp_port "NTRIP_PORT" "$INSTALL_NTRIP_PORT"

    # The application runs as an unprivileged service account and the unit
    # grants no CAP_NET_BIND_SERVICE, so it cannot bind ports below 1024 - the
    # process would die with "PermissionError: [Errno 13]" on startup. Public
    # HTTP/HTTPS is served by nginx on 80/443, which proxies to WEB_PORT.
    for _port_check in "WEB_PORT:$INSTALL_WEB_PORT" "NTRIP_PORT:$INSTALL_NTRIP_PORT"; do
        _port_label="${_port_check%%:*}"
        _port_number="${_port_check##*:}"
        if [ "$_port_number" -lt 1024 ]; then
            echo "ERROR: $_port_label must be 1024 or higher, got '$_port_number'."
            echo "  The caster runs unprivileged and cannot bind privileged ports."
            if [ "$_port_label" = "WEB_PORT" ]; then
                echo "  This is the internal backend port behind nginx - not the public one."
                echo "  nginx already serves 80/443; keep the backend on e.g. 8080 and"
                echo "  enable HTTPS with TLS_MODE instead."
            fi
            exit 1
        fi
    done

    if [ "$INSTALL_WEB_PORT" -eq "$INSTALL_NTRIP_PORT" ]; then
        echo "ERROR: WEB_PORT and NTRIP_PORT must be different"
        exit 1
    fi
}

validate_python_version() {
    local python_version

    if ! command -v python3 >/dev/null 2>&1; then
        return 1
    fi

    if ! python3 - <<'PYTHON_VERSION_CHECK'
import sys
raise SystemExit(0 if sys.version_info >= (3, 11) else 1)
PYTHON_VERSION_CHECK
    then
        python_version=$(python3 -c 'import sys; print(".".join(map(str, sys.version_info[:3])))' 2>/dev/null || echo unknown)
        echo "ERROR: Python 3.11 or newer is required; found Python ${python_version}." >&2
        return 1
    fi

    return 0
}

run_preflight_checks() {
    local free_kb
    local free_mb
    local os_name="unknown"
    local os_id="unknown"

    echo "Running pre-flight checks..."

    if ! command -v apt >/dev/null 2>&1; then
        echo "ERROR: apt is required. This installer targets Debian/Raspberry Pi OS/Ubuntu systems."
        exit 1
    fi

    if ! command -v systemctl >/dev/null 2>&1; then
        echo "ERROR: systemctl is required. This installer expects a systemd-based system."
        exit 1
    fi

    if command -v python3 >/dev/null 2>&1; then
        validate_python_version || exit 1
    else
        echo "Python 3 is not installed yet; the installer will install it and verify Python >= 3.11 afterward."
    fi

    if [ ! -d /run/systemd/system ]; then
        echo "ERROR: systemd does not appear to be PID 1 on this system."
        exit 1
    fi

    free_kb=$(df -Pk / 2>/dev/null | awk 'NR==2 {print $4}')
    case "$free_kb" in
        ''|*[!0-9]*)
            free_kb=0
            ;;
    esac
    free_mb=$((free_kb / 1024))
    if [ "$free_mb" -lt 1024 ]; then
        echo "ERROR: At least 1024 MB free disk space is required on /. Found: ${free_mb} MB"
        exit 1
    fi

    if [ -r /etc/os-release ]; then
        os_name=$(awk -F= '$1=="PRETTY_NAME" {gsub(/^"|"$/, "", $2); print $2}' /etc/os-release)
        os_id=$(awk -F= '$1=="ID" {gsub(/^"|"$/, "", $2); print $2}' /etc/os-release)
    fi

    case "$os_id" in
        debian|raspbian|ubuntu)
            echo "OS check: ${os_name:-$os_id}"
            ;;
        *)
            echo "WARNING: Untested OS '${os_name:-$os_id}'. Supported targets are Debian, Raspberry Pi OS, and Ubuntu."
            ;;
    esac

    for path in /opt /etc /var/log; do
        if [ ! -d "$path" ] || [ ! -w "$path" ]; then
            echo "ERROR: Required writable directory is not available: $path"
            exit 1
        fi
    done

    if [ "$TLS_MODE" = "letsencrypt" ]; then
        if [ "$TLS_DOMAIN" = "_" ] || [ -z "$TLS_DOMAIN" ]; then
            echo "ERROR: Let's Encrypt requires a real TLS_DOMAIN"
            exit 1
        fi
    fi

    echo "Pre-flight checks passed."
}

ensure_service_account() {
    echo "Ensuring dedicated service account..."

    if ! getent group "$SERVICE_GROUP" >/dev/null 2>&1; then
        groupadd --system "$SERVICE_GROUP"
    fi

    if ! id "$SERVICE_USER" >/dev/null 2>&1; then
        useradd \
            --system \
            --gid "$SERVICE_GROUP" \
            --home-dir "$BASE" \
            --shell /usr/sbin/nologin \
            --comment "GNSS Caster service account" \
            "$SERVICE_USER"
    fi

    for supplemental_group in dialout tty bluetooth; do
        if ! getent group "$supplemental_group" >/dev/null 2>&1; then
            groupadd --system "$supplemental_group" 2>/dev/null || true
        fi
        if getent group "$supplemental_group" >/dev/null 2>&1; then
            usermod -a -G "$supplemental_group" "$SERVICE_USER" 2>/dev/null || true
        fi
    done
    ensure_admission_lock
}

# BEGIN GENERATED RELEASE UPDATER
write_release_updater() {
    install -d -o root -g root -m 700 /var/lib/gnss-caster-updates
    cat > "$BASE/release-update.py" << 'PYTHON_RELEASE_UPDATER'
"""Root-owned stable-release updater; stdlib only, no application imports.

The trust boundary is HTTPS GitHub Releases in the fixed owner/repository. An
asset digest verifies integrity, not an independent publisher signature.
"""
import contextlib
import hashlib
import json
import os
from pathlib import Path
import re
import shutil
import signal
import sqlite3
import stat
import subprocess
import sys
import tempfile
import time
import urllib.error
import urllib.parse
import urllib.request

REPO = 'stepm65/GNSS-Caster'
API = f'https://api.github.com/repos/{REPO}/releases'
BASE = Path('/opt/gnss-caster')
STORE = Path('/var/lib/gnss-caster-updates')
UNIT = 'gnss-caster-release-update.service'
MAX_ASSET = 20 * 1024 * 1024
MAX_JSON = 1024 * 1024
BUSY = {'queued', 'checking', 'downloading', 'installing'}
STAGE_TIMEOUTS = {'snapshot': 600, 'dependencies': 1800, 'configuration': 900,
                  'migration': 600, 'health': 300, 'rollback': 900}
INSTALL_TIMEOUT = 3600
ROLLBACK_TIMEOUT = 900
HEARTBEAT_SECONDS = 5
CLEAN_ENV = {'PATH': '/usr/sbin:/usr/bin:/sbin:/bin', 'LANG': 'C.UTF-8',
             'HOME': '/root', 'DEBIAN_FRONTEND': 'noninteractive'}


class UpdateError(Exception):
    pass


def version(value):
    match = re.fullmatch(r'v?(0|[1-9][0-9]{0,3})\.(0|[1-9][0-9]{0,3})\.(0|[1-9][0-9]{0,3})', str(value))
    if not match:
        raise UpdateError('Unsupported release version')
    return tuple(map(int, match.groups()))


def current_version():
    source = (BASE / 'app/version.py').read_text(encoding='utf-8')
    match = re.search(r'^__version__ = [\'"]([0-9.]+)[\'"]$', source, re.M)
    if not match:
        raise UpdateError('Cannot determine installed version')
    version(match[1])
    return match[1]


def allowed_url(url):
    parsed = urllib.parse.urlsplit(url)
    return (parsed.scheme == 'https' and parsed.port in (None, 443)
            and not parsed.username and not parsed.password
            and parsed.hostname in {'api.github.com', 'github.com',
                                    'release-assets.githubusercontent.com', 'objects.githubusercontent.com'})


class GitHubRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        if not allowed_url(newurl):
            raise UpdateError('Untrusted download redirect')
        return super().redirect_request(req, fp, code, msg, headers, newurl)


def fetch(url, limit):
    if not allowed_url(url):
        raise UpdateError('Untrusted release URL')
    # Do not let service-controlled proxy environment redirect root traffic.
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}), GitHubRedirect())
    request = urllib.request.Request(url, headers={
        'Accept': 'application/vnd.github+json' if url.startswith(API) else 'application/octet-stream',
        'User-Agent': 'GNSS-Caster-Release-Updater', 'X-GitHub-Api-Version': '2022-11-28',
    })
    deadline = time.monotonic() + (20 if limit == MAX_JSON else 120)
    try:
        with opener.open(request, timeout=10) as response:
            length = int(response.headers.get('Content-Length', '0'))
            if length > limit:
                raise UpdateError('Release download exceeds size limit')
            chunks, total = [], 0
            while True:
                if time.monotonic() > deadline:
                    raise UpdateError('Release download timed out')
                chunk = response.read(min(65536, limit + 1 - total))
                if not chunk:
                    break
                chunks.append(chunk)
                total += len(chunk)
                if total > limit:
                    raise UpdateError('Release download exceeds size limit')
            return b''.join(chunks)
    except urllib.error.HTTPError as error:
        if error.code == 404 and url == API + '/latest':
            return b'null'
        raise UpdateError(f'GitHub request failed (HTTP {error.code})') from error
    except (OSError, ValueError) as error:
        raise UpdateError('Cannot contact GitHub securely; check network and system clock') from error


def release_candidate(data, installed):
    if data is None:
        return None
    if not isinstance(data, dict) or data.get('draft') is not False or data.get('prerelease') is not False:
        raise UpdateError('Only published stable releases are supported')
    tag = data.get('tag_name', '')
    if not re.fullmatch(r'v[0-9]+\.[0-9]+\.[0-9]+', tag):
        raise UpdateError('Unsupported release version')
    target = version(tag)
    assets = [item for item in data.get('assets', []) if item.get('name') == 'gnss-caster-install.sh']
    if len(assets) != 1:
        raise UpdateError('Release has no unique installer asset')
    asset = assets[0]
    digest = str(asset.get('digest') or '')
    if not re.fullmatch(r'sha256:[0-9a-f]{64}', digest):
        raise UpdateError('Release installer has no SHA-256 digest')
    url = f'https://github.com/{REPO}/releases/download/{tag}/gnss-caster-install.sh'
    if asset.get('browser_download_url') != url or asset.get('state') != 'uploaded':
        raise UpdateError('Unexpected release installer URL or state')
    size = asset.get('size')
    if type(size) is not int or not 1 <= size <= MAX_ASSET:
        raise UpdateError('Release installer has an invalid size')
    return {'tag': tag, 'version': '.'.join(map(str, target)), 'sha256': digest[7:],
            'size': size, 'download_url': url, 'available': target > version(installed),
            'url': f'https://github.com/{REPO}/releases/tag/{tag}',
            'notes': str(data.get('body') or '')[:12000], 'published_at': data.get('published_at')}


def ensure_store():
    STORE.mkdir(mode=0o700, parents=False, exist_ok=True)
    info = STORE.lstat()
    if not stat.S_ISDIR(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o077:
        raise UpdateError('Update storage must be a private root-owned directory')


def read_json(name, default=None):
    path = STORE / name
    if not path.exists():
        return default
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1:
        raise UpdateError('Unsafe update state file')
    return json.loads(path.read_text(encoding='utf-8'))


def write_json(name, data):
    fd, temporary = tempfile.mkstemp(prefix='.state-', dir=STORE)
    try:
        with os.fdopen(fd, 'w', encoding='utf-8') as handle:
            json.dump(data, handle, ensure_ascii=True)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, STORE / name)
        if os.name == 'posix':
            directory_fd = os.open(STORE, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory_fd)
            finally:
                os.close(directory_fd)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)


@contextlib.contextmanager
def lock(path):
    import fcntl
    fd = os.open(path, os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600)
    try:
        info = os.fstat(fd)
        if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_nlink != 1:
            raise UpdateError('Unsafe maintenance lock')
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as error:
            raise UpdateError('Another maintenance operation is running') from error
        yield fd
    finally:
        os.close(fd)


def run(arguments, **kwargs):
    return subprocess.run(arguments, env=CLEAN_ENV, text=True, **kwargs)


def boot_id():
    return Path('/proc/sys/kernel/random/boot_id').read_text().strip()


def recovery_status():
    helper = Path('/var/lib/gnss-caster-maintenance/recovery.py')
    if not helper.exists():
        return []  # Bootstrap from an older runtime without durable journals.
    info = helper.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_uid != 0 or info.st_mode & 0o022:
        raise UpdateError('Unsafe recovery helper')
    result = run(['/usr/bin/python3', '-I', str(helper), 'status'], capture_output=True, timeout=15)
    if result.returncode:
        raise UpdateError('Cannot read recovery journal; inspect it locally before updating')
    return json.loads(result.stdout)


def status():
    state = read_json('state.json', {'status': 'idle'})
    if state['status'] in BUSY:
        result = run(['/usr/bin/systemctl', 'show', UNIT, '--property=ActiveState', '--value'],
                     capture_output=True, timeout=10)
        active = result.stdout.strip() in ('active', 'activating', 'reloading', 'deactivating')
        if state.get('boot_id') != boot_id() or (not active and time.time() - state['started_at'] > 30):
            # A power cut/SIGKILL is not a successful rollback.
            state = dict(state, status='interrupted', message='Update interrupted; inspect the maintenance log',
                         finished_at=int(time.time()))
            write_json('state.json', state)
    recovery = recovery_status()
    if state['status'] in ('failed', 'interrupted') and state.get('snapshot'):
        restored = next((item for item in recovery
                         if item['snapshot'] == state['snapshot'] and item['phase'] == 'rolled_back'), None)
        if restored:
            state = dict(state, status='rolled_back', message='Previous version restored by local recovery',
                         finished_at=restored['updated_at'])
            write_json('state.json', state)
    installed = current_version()
    checked = read_json('candidate.json')
    if checked and checked.get('candidate'):
        checked['candidate']['available'] = version(checked['candidate']['tag']) > version(installed)
    return {'current_version': installed, 'job': state,
            'release': checked, 'repository': f'https://github.com/{REPO}',
            'recovery': [item for item in recovery if item['phase'] not in ('committed', 'rolled_back', 'snapshot_failed')]}


def check():
    installed = current_version()
    candidate = release_candidate(json.loads(fetch(API + '/latest', MAX_JSON)), installed)
    result = {'checked_at': int(time.time()), 'candidate': candidate}
    write_json('candidate.json', result)
    return dict(result, current_version=installed)


def active_rovers():
    # Read counters only. No import of code/config from the service account.
    path = BASE / 'instance/db.sqlite'
    config = (BASE / 'instance/config.yaml').read_text(encoding='utf-8')
    configured = re.findall(r'^\s+path:\s*[\'"]?([^\s\'"#]+)[\'"]?\s*(?:#.*)?$', config, re.M)
    if configured != [str(path)]:
        raise UpdateError('Web updates require the standard database location')
    with contextlib.closing(sqlite3.connect(path.as_uri() + '?mode=ro', uri=True, timeout=5)) as db:
        field = db.execute("SELECT value FROM system_setting WHERE key='field_work_active'").fetchone()
        if field and str(field[0]).lower() in ('1', 'true', 'yes', 'on'):
            raise UpdateError('Finish field work mode before maintenance')
        return int(db.execute('SELECT COALESCE(SUM(active_conn), 0) FROM rover').fetchone()[0])


def preflight_space():
    # Repair snapshots app, venv and DB. Keep headroom for pip and an additional
    # copy; this is conservative rather than a promise for arbitrary releases.
    total = 0
    for directory in (BASE / 'app', BASE / 'venv', BASE / 'instance'):
        for root, dirs, files in os.walk(directory, followlinks=False):
            for filename in files:
                total += (Path(root) / filename).lstat().st_size
    required = total * 2 + 512 * 1024 * 1024
    for directory in (BASE, Path('/var/backups'), STORE):
        if shutil.disk_usage(directory).free < required:
            raise UpdateError('Not enough free space for update and rollback snapshot')


def start(tag, digest):
    version(tag)
    if not re.fullmatch(r'[0-9a-f]{64}', digest):
        raise UpdateError('Invalid release digest')
    with lock(STORE / 'request.lock'):
        current = status()
        if current['job']['status'] in BUSY:
            raise UpdateError('An update is already running')
        if current.get('recovery'):
            raise UpdateError('Unfinished maintenance requires local recovery before updating')
        checked = read_json('candidate.json', {})
        candidate = checked.get('candidate') or {}
        if time.time() - checked.get('checked_at', 0) > 600 or candidate.get('tag') != tag or candidate.get('sha256') != digest:
            raise UpdateError('Check for updates again before installing')
        if version(tag) <= version(current_version()):
            raise UpdateError('Only a newer release can be installed')
        if active_rovers():
            raise UpdateError('Disconnect all rovers before updating')
        preflight_space()
        # Confirm the other maintenance lock is currently free. The worker
        # obtains and retains it again before doing any work.
        with lock(Path('/run/gnss-caster-maintenance.lock')):
            pass
        run(['/usr/bin/systemctl', 'stop', UNIT], capture_output=True, timeout=15)
        run(['/usr/bin/systemctl', 'reset-failed', UNIT], capture_output=True, timeout=15)
        state = {'status': 'queued', 'tag': tag, 'sha256': digest, 'previous_version': current_version(),
                 'started_at': int(time.time()), 'boot_id': boot_id(), 'message': 'Update queued'}
        write_json('state.json', state)
        try:
            result = run(['/usr/bin/systemd-run', '--unit=' + UNIT, '--property=Type=oneshot',
                          '--property=RemainAfterExit=yes', '--property=UMask=0077',
                          '--property=TimeoutStartSec=infinity', f'--property=TimeoutStopSec={ROLLBACK_TIMEOUT + 60}',
                          '--property=KillMode=mixed', '/usr/bin/python3', '-I',
                          str(BASE / 'release-update.py'), 'worker', tag, digest],
                         capture_output=True, timeout=20)
            if result.returncode:
                raise UpdateError('Could not schedule update service')
        except Exception:
            # Scheduling timeout can be ambiguous; status reconciles with the
            # actual unit, and the API never retries a destructive request.
            raise UpdateError('Update scheduling was not confirmed; check status before retrying')
        return state


def install_asset(candidate, content):
    if len(content) != candidate['size'] or hashlib.sha256(content).hexdigest() != candidate['sha256']:
        raise UpdateError('Downloaded installer failed SHA-256 verification')
    text = content.decode('utf-8')
    match = re.search(r'^CASTER_VERSION="([0-9.]+)"$', text, re.M)
    if not match or match[1] != candidate['version']:
        raise UpdateError('Installer version does not match the release')
    path = STORE / 'installer.sh'
    # The store is root-only; replacement never follows a prior symlink.
    fd, temporary = tempfile.mkstemp(prefix='.installer-', dir=STORE)
    try:
        with os.fdopen(fd, 'wb') as handle:
            handle.write(content)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
    finally:
        if os.path.exists(temporary):
            os.unlink(temporary)
    return path


def record_installer_progress(line, state):
    """Keep recovery coordinates while repair runs, not only after its exit."""
    snapshot = re.fullmatch(r'Rollback snapshot created: (/var/backups/gnss-caster/rollback-[^\s/]+)', line)
    if snapshot:
        state['snapshot'] = snapshot[1]
    if line.startswith('GNSS maintenance stage: '):
        name = line.removeprefix('GNSS maintenance stage: ')
        if name in STAGE_TIMEOUTS:
            state['phase'] = name
    if line == 'Rollback completed; previous service state restored.':
        state['rollback_confirmed'] = True


def run_installation(arguments, *, stdout, pass_fds, state):
    """Forward one stop request and allow rollback before escalating.

    A separate process group lets Bash and its current external command receive
    TERM together. The supervisor stays alive so systemd mixed mode cannot kill
    the rollback immediately after the main process exits.
    """
    requested = []
    previous = {}
    process = None
    stopping_at = None
    phase = 'snapshot'

    def request_stop(signum, frame):
        if not requested:
            requested.append('signal')

    def terminate_group(sig):
        try:
            os.killpg(process.pid, sig)
        except ProcessLookupError:
            pass

    try:
        for sig in (signal.SIGTERM, signal.SIGINT):
            previous[sig] = signal.signal(sig, request_stop)
        if requested:
            raise UpdateError('Update stopped before installation')
        process = subprocess.Popen(arguments, env=CLEAN_ENV, text=True, stdout=stdout,
                                   stderr=subprocess.STDOUT, pass_fds=pass_fds, start_new_session=True)
        started = phase_started = last_heartbeat = time.monotonic()
        phase = state.get('phase', 'snapshot')
        partial = ''
        with (STORE / 'maintenance.log').open(encoding='utf-8', errors='replace') as progress:
            while True:
                chunk = progress.read(256 * 1024)
                lines = (partial + chunk).split('\n')
                partial = lines.pop()[-65536:]
                coordinates = (state.get('snapshot'), state.get('phase'), state.get('rollback_confirmed'))
                for line in lines:
                    record_installer_progress(line.strip(), state)
                if coordinates != (state.get('snapshot'), state.get('phase'), state.get('rollback_confirmed')):
                    write_json('state.json', state)
                now = time.monotonic()
                next_phase = state.get('phase', phase)
                if next_phase != phase:
                    phase, phase_started = next_phase, now
                result = process.poll()
                if result is not None:
                    # Drain the remaining log before accepting a final result.
                    if chunk:
                        continue
                    record_installer_progress(partial.strip(), state)
                    return subprocess.CompletedProcess(arguments, result)
                if not requested and (now - started >= INSTALL_TIMEOUT or
                                      now - phase_started >= STAGE_TIMEOUTS.get(phase, 900)):
                    requested.append('timeout')
                if requested and stopping_at is None:
                    state['stop_reason'] = requested[0]
                    state['stop_requested_at'] = int(time.time())
                    state['message'] = 'Stopping update; waiting for rollback'
                    write_json('state.json', state)
                    # A rollback triggered by repair itself must not be interrupted.
                    if phase != 'rollback':
                        terminate_group(signal.SIGTERM)
                    stopping_at = now
                if stopping_at is not None and now - stopping_at >= ROLLBACK_TIMEOUT:
                    state['termination_escalated'] = True
                    write_json('state.json', state)
                    terminate_group(signal.SIGKILL)
                    process.wait(timeout=30)
                    raise UpdateError('Update could not stop safely; inspect the recovery snapshot')
                if now - last_heartbeat >= HEARTBEAT_SECONDS:
                    state['heartbeat_at'] = int(time.time())
                    write_json('state.json', state)
                    last_heartbeat = now
                try:
                    process.wait(timeout=1)
                except subprocess.TimeoutExpired:
                    pass
    finally:
        # An exception in state/log handling must not leave an untracked installer.
        try:
            if process is not None and process.poll() is None:
                if stopping_at is None and phase != 'rollback':
                    terminate_group(signal.SIGTERM)
                try:
                    process.wait(timeout=ROLLBACK_TIMEOUT)
                except subprocess.TimeoutExpired:
                    terminate_group(signal.SIGKILL)
                    process.wait(timeout=30)
        finally:
            for sig, handler in previous.items():
                signal.signal(sig, handler)


def worker(tag, digest):
    state = read_json('state.json')
    if not state or state.get('tag') != tag or state.get('sha256') != digest or state['status'] != 'queued':
        raise UpdateError('No matching update request')

    def stage(name, message):
        state.update(status=name, message=message)
        write_json('state.json', state)

    try:
        with lock(Path('/run/gnss-caster-maintenance.lock')) as maintenance_fd:
            (STORE / 'maintenance.log').write_text(f'Updating to {tag}\n', encoding='utf-8')
            stage('checking', 'Validating stable release')
            candidate = release_candidate(json.loads(fetch(API + '/tags/' + tag, MAX_JSON)), current_version())
            if not candidate or not candidate['available'] or candidate['sha256'] != digest:
                raise UpdateError('Release changed; check for updates again')
            if active_rovers():
                raise UpdateError('Disconnect all rovers before updating')
            preflight_space()
            stage('downloading', 'Downloading and verifying installer')
            path = install_asset(candidate, fetch(candidate['download_url'], MAX_ASSET))
            syntax = run(['/bin/bash', '-n', str(path)], capture_output=True, timeout=15)
            if syntax.returncode:
                raise UpdateError('Release installer syntax check failed')
            if active_rovers():
                raise UpdateError('Disconnect all rovers before updating')
            # Existing repair transaction uses fd 8. Pass the same open-file
            # description so child flock recognizes ownership without bypasses.
            os.dup2(maintenance_fd, 8, inheritable=True)
            try:
                stage('installing', 'Installing; web interface may reconnect')
                with (STORE / 'maintenance.log').open('a', encoding='utf-8') as log:
                    result = run_installation(['/bin/bash', str(path), '--repair'], stdout=log,
                                              pass_fds=(8,), state=state)
                rolled_back = False
                with (STORE / 'maintenance.log').open(encoding='utf-8', errors='replace') as log:
                    for line in iter(lambda: log.readline(65536), ''):
                        snapshot = re.fullmatch(r'Rollback snapshot created: (/var/backups/gnss-caster/[^\s]+)\s*', line)
                        if snapshot:
                            state['snapshot'] = snapshot[1]
                        if line.strip() == 'Rollback completed; previous service state restored.':
                            rolled_back = True
                if result.returncode or state.get('stop_reason'):
                    if rolled_back:
                        stage('rolled_back', 'Update failed; previous version restored')
                    else:
                        stage('failed', 'Update failed; inspect the maintenance log')
                elif current_version() != candidate['version']:
                    stage('failed', 'Installed version could not be confirmed; inspect the maintenance log')
                else:
                    stage('succeeded', 'Update installed successfully; reload the page')
            finally:
                if maintenance_fd != 8:
                    os.close(8)
    except Exception as error:
        message = str(error) if isinstance(error, UpdateError) else 'Update failed; inspect the maintenance log'
        stage('interrupted' if state.get('termination_escalated') else 'failed', message)
    finally:
        state['finished_at'] = int(time.time())
        write_json('state.json', state)
    return state


def main():
    if os.geteuid() != 0:
        raise UpdateError('Updater requires root')
    os.umask(0o077)
    ensure_store()
    args = sys.argv[1:]
    if args == ['check']:
        result = check()
    elif args == ['status']:
        result = status()
    elif len(args) == 3 and args[0] == 'start':
        result = start(*args[1:])
    elif len(args) == 3 and args[0] == 'worker':
        result = worker(*args[1:])
    else:
        raise UpdateError('Unsupported updater command')
    print(json.dumps(result, ensure_ascii=True))


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        print(json.dumps({'error': str(error) if isinstance(error, UpdateError) else 'Update operation failed'}))
        sys.exit(1)

PYTHON_RELEASE_UPDATER
    chown root:root "$BASE/release-update.py"
    chmod 700 "$BASE/release-update.py"
}
# END GENERATED RELEASE UPDATER

write_privileged_helper() {
    # Privilege-separation core. The application runs as an unprivileged account
    # and must never hold blanket sudo. Instead it may run exactly one root
    # binary - this helper - whose every subcommand strictly validates its
    # arguments (systemd unit name, RFCOMM channel, Bluetooth MAC, backup name)
    # before acting, so a compromised web process cannot escalate beyond the
    # narrow, audited operations defined below. The matching sudoers entry
    # further down whitelists only these subcommands NOPASSWD; nothing else.
    mkdir -p "$BASE"

    write_release_updater

cat > "$PRIVILEGED_HELPER" << 'EOF'
#!/bin/bash
set -euo pipefail

export PATH="/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin"
SERVICE_GROUP="gnss-caster"

die() {
    echo "ERROR: $*" >&2
    exit 1
}

need_root() {
    if [ "${EUID:-$(id -u)}" -ne 0 ]; then
        die "privileged helper must run as root"
    fi
}

validate_unit_name() {
    local unit_name="$1"
    [[ "$unit_name" =~ ^gnss-caster-[a-z0-9-]+\.service$ ]] || die "invalid unit name"
}

validate_channel() {
    local channel="$1"
    [[ "$channel" =~ ^[0-9]+$ ]] || die "invalid RFCOMM channel"
    [ "$channel" -ge 1 ] && [ "$channel" -le 30 ] || die "RFCOMM channel must be 1..30"
}

validate_mac() {
    local mac="$1"
    [[ "$mac" =~ ^([0-9A-Fa-f]{2}[:-]){5}[0-9A-Fa-f]{2}$ ]] || die "invalid Bluetooth MAC"
}

validate_backup_name() {
    local safe_name="$1"
    [ "$(basename -- "$safe_name")" = "$safe_name" ] || die "backup name must not contain paths"
    if [[ "$safe_name" != backup_*.tar.gz ]] && [[ "$safe_name" != backup_*.tar.gz.enc ]]; then
        die "invalid backup name"
    fi
}

backup_interval_to_cron_expression() {
    local interval_seconds="$1"
    local interval_minutes
    local interval_hours
    local interval_days

    [[ "$interval_seconds" =~ ^[0-9]+$ ]] || interval_seconds=86400
    [ "$interval_seconds" -ge 3600 ] || interval_seconds=3600
    [ "$interval_seconds" -le 604800 ] || interval_seconds=604800

    interval_minutes=$(( (interval_seconds + 30) / 60 ))
    [ "$interval_minutes" -ge 60 ] || interval_minutes=60

    if [ "$interval_minutes" -lt 1440 ] && [ $((interval_minutes % 60)) -eq 0 ]; then
        interval_hours=$((interval_minutes / 60))
        [ "$interval_hours" -ge 1 ] || interval_hours=1
        if [ "$interval_hours" -eq 24 ]; then
            printf '0 2 * * *\n'
            return
        fi
        printf '0 */%s * * *\n' "$interval_hours"
        return
    fi

    if [ $((interval_minutes % 1440)) -eq 0 ]; then
        interval_days=$((interval_minutes / 1440))
        [ "$interval_days" -ge 1 ] || interval_days=1
        if [ "$interval_days" -le 28 ]; then
            printf '0 2 */%s * *\n' "$interval_days"
            return
        fi
    fi

    printf '0 2 * * *\n'
}

need_root
action="${1:-}"

# Audit every privileged invocation. Arguments here are non-secret control
# values (unit names, channels, MACs), so logging them aids incident review.
audit_privileged_call() {
    local audit_log="/var/log/gnss-caster/privileged-helper.log"
    local caller_uid="${SUDO_UID:-unknown}"
    local caller_user="${SUDO_USER:-unknown}"
    local ts

    ts=$(date -Is 2>/dev/null || date)
    mkdir -p /var/log/gnss-caster 2>/dev/null || true
    printf '%s uid=%s user=%s action=%s args=%s\n' \
        "$ts" "$caller_uid" "$caller_user" "$action" "$*" \
        >> "$audit_log" 2>/dev/null || true
    chmod 640 "$audit_log" 2>/dev/null || true
}

# Status is polled every five seconds; record checks and installation requests,
# but avoid filling the maintenance log with read-only polling.
if [ "$action" != "release-status" ]; then
    audit_privileged_call "$@"
fi

case "$action" in
    release-check|release-status)
        [ "$#" -eq 1 ] || die "unexpected release arguments"
        exec /usr/bin/python3 -I /opt/gnss-caster/release-update.py "${action#release-}"
        ;;
    release-install)
        [ "$#" -eq 3 ] || die "release tag and SHA-256 are required"
        [[ "$2" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] || die "invalid release tag"
        [[ "$3" =~ ^[0-9a-f]{64}$ ]] || die "invalid release digest"
        exec /usr/bin/python3 -I /opt/gnss-caster/release-update.py start "$2" "$3"
        ;;
    rfkill-unblock-bluetooth)
        exec rfkill unblock bluetooth
        ;;

    systemctl-is-active)
        unit_name="${2:-}"
        case "$unit_name" in
            bluetooth|gnss-caster|nginx|fail2ban|cron|ssh|sshd)
                exec systemctl is-active --quiet "$unit_name"
                ;;
            *)
                die "unsupported systemctl status unit"
                ;;
        esac
        ;;

    systemctl-start)
        unit_name="${2:-}"
        [ "$unit_name" = "bluetooth" ] || die "only bluetooth can be started by this helper"
        exec systemctl start bluetooth
        ;;

    rfcomm-bind)
        bind_channel="${2:-}"
        mac_address="${3:-}"
        target_channel="${4:-}"
        validate_channel "$bind_channel"
        validate_channel "$target_channel"
        validate_mac "$mac_address"
        exec rfcomm bind "$bind_channel" "$mac_address" "$target_channel"
        ;;

    rfcomm-release)
        release_channel="${2:-}"
        validate_channel "$release_channel"
        exec rfcomm release "$release_channel"
        ;;

    set-system-clock)
        # GNSS-derived time for a host with no RTC and no internet. Strictly
        # validated: this runs as root and the argument comes from a parsed
        # NMEA sentence.
        clock_value="${2:-}"
        case "$clock_value" in
            [0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]\ [0-2][0-9]:[0-5][0-9]:[0-5][0-9]) ;;
            *) die "invalid timestamp" ;;
        esac
        # Stop NTP from fighting us, then set the clock in UTC.
        timedatectl set-ntp false >/dev/null 2>&1 || true
        exec timedatectl set-time "$clock_value"
        ;;

    guarded-service-action)
        [ "$#" -eq 2 ] || die "service action required"
        case "$2" in restart|reboot) ;; *) die "unsupported service action" ;; esac
        source /opt/gnss-caster/sqlite-functions.sh
        acquire_maintenance_lock
        acquire_admission_guard
        if [ "$2" = restart ]; then
            exec systemctl restart gnss-caster
        fi
        was_active=false
        systemctl is-active --quiet gnss-caster && was_active=true
        systemctl stop gnss-caster
        if ! systemctl reboot; then
            # A rejected reboot must not silently leave a working caster down.
            if [ "$was_active" = true ]; then
                systemctl start gnss-caster || die "reboot failed and caster could not be restarted"
            fi
            die "reboot failed"
        fi
        ;;

    reboot-host)
        source /opt/gnss-caster/sqlite-functions.sh
        acquire_maintenance_lock
        acquire_admission_guard
        # Deliberately delayed and detached: the caller needs to return so the
        # confirmation can reach the operator before the machine goes down.
        exec systemd-run \
            --unit "gnss-caster-reboot.service" \
            --description "GNSS Caster requested reboot" \
            --on-active=8 \
            --timer-property=AccuracySec=1s \
            /opt/gnss-caster/gnss-caster-privileged-helper.sh guarded-service-action reboot
        ;;

    restart-service)
        source /opt/gnss-caster/sqlite-functions.sh
        acquire_maintenance_lock
        acquire_admission_guard
        # The gentler option: restarting the caster clears most stuck states
        # without losing the host. Detached for the same reason - this command
        # would otherwise kill the process that asked for it.
        exec systemd-run \
            --unit "gnss-caster-restart.service" \
            --description "GNSS Caster requested service restart" \
            --on-active=4 \
            --timer-property=AccuracySec=1s \
            /opt/gnss-caster/gnss-caster-privileged-helper.sh guarded-service-action restart
        ;;

    recover-bluetooth-deep)
        # Preserve pairing keys: removing a device can prevent unattended
        # reconnection. A controller reset is not proof of restored data flow.
        deep_mac="${2:-}"
        [ -n "$deep_mac" ] && validate_mac "$deep_mac"

        systemctl stop bluetooth >/dev/null 2>&1 || true
        rfkill block bluetooth >/dev/null 2>&1 || true
        sleep 2
        rfkill unblock bluetooth >/dev/null 2>&1 || true
        sleep 2
        systemctl start bluetooth >/dev/null 2>&1 || true
        sleep 3
        hciconfig hci0 up >/dev/null 2>&1 || true
        exec hciconfig hci0
        ;;

    recover-bluetooth)
        # The Pi's controller occasionally reaches a state where scanning still
        # works but no classic connection can be made ("Host is down"), and only
        # a reboot clears it. This is a limited recovery attempt; it does not
        # reinitialize every driver/firmware state like a reboot does.
        hciconfig hci0 down >/dev/null 2>&1 || true
        sleep 1
        hciconfig hci0 up >/dev/null 2>&1 || true
        sleep 1
        systemctl restart bluetooth >/dev/null 2>&1 || true
        sleep 2
        hciconfig hci0 up >/dev/null 2>&1 || true
        exec hciconfig hci0
        ;;

    read-rssi)
        # Live signal strength of an *established* link. BlueZ only exposes
        # RSSI over D-Bus while scanning, so a connected receiver otherwise
        # shows "no recent scan". hcitool reads it straight from the HCI
        # connection, which needs privileges - hence this subcommand.
        rssi_mac="${2:-}"
        validate_mac "$rssi_mac"
        exec hcitool rssi "$rssi_mac"
        ;;

    systemd-job)
        job_type="${2:-}"
        unit_name="${3:-}"
        validate_unit_name "$unit_name"

        case "$job_type" in
            backup)
                exec systemd-run \
                    --unit "$unit_name" \
                    --description "GNSS Caster backup job" \
                    --property=Type=oneshot \
                    --property=RemainAfterExit=yes \
                    --property=WorkingDirectory=/opt/gnss-caster \
                    /opt/gnss-caster/backup.sh
                ;;
            restore)
                backup_name="${4:-}"
                validate_backup_name "$backup_name"
                # Optional passphrase file for an encrypted archive. A path is
                # passed rather than the secret itself: command lines are world
                # readable through /proc, a 0600 file is not. restore.sh deletes
                # it after reading.
                passphrase_file="${5:-}"
                if [ -n "$passphrase_file" ]; then
                    case "$passphrase_file" in
                        /run/gnss-caster/restore-*.key) ;;
                        *) die "unexpected passphrase file path" ;;
                    esac
                    [[ "$passphrase_file" =~ ^/run/gnss-caster/restore-[0-9a-f]{16}\.key$ ]] || die "invalid passphrase filename"
                    [ -f "$passphrase_file" ] && [ ! -L "$passphrase_file" ] || die "invalid passphrase file"
                    exec systemd-run \
                        --unit "$unit_name" \
                        --description "GNSS Caster restore job" \
                        --property=Type=oneshot \
                        --property=RemainAfterExit=yes \
                        --property=WorkingDirectory=/opt/gnss-caster \
                        /opt/gnss-caster/restore.sh "$backup_name" "$passphrase_file"
                fi
                exec systemd-run \
                    --unit "$unit_name" \
                    --description "GNSS Caster restore job" \
                    --property=Type=oneshot \
                    --property=RemainAfterExit=yes \
                    --property=WorkingDirectory=/opt/gnss-caster \
                    /opt/gnss-caster/restore.sh "$backup_name"
                ;;
            *)
                die "unsupported systemd job type"
                ;;
        esac
        ;;

    write-logrotate)
        rotation_days="${2:-30}"
        [[ "$rotation_days" =~ ^[0-9]+$ ]] || die "invalid log retention"
        [ "$rotation_days" -ge 1 ] && [ "$rotation_days" -le 3650 ] || die "log retention must be 1..3650"
        cat > /etc/logrotate.d/gnss-caster << LOGROTATE
/var/log/gnss-caster/*.log {
    daily
    missingok
    rotate $rotation_days
    compress
    delaycompress
    notifempty
    create 660 root $SERVICE_GROUP
    sharedscripts
    postrotate
        systemctl reload gnss-caster > /dev/null 2>&1 || true
    endscript
}
LOGROTATE
        chmod 644 /etc/logrotate.d/gnss-caster
        ;;

    write-backup-cron)
        enabled="${2:-0}"
        interval_seconds="${3:-86400}"
        cron_path="/etc/cron.d/gnss-caster-backup"
        mkdir -p /etc/cron.d
        case "$enabled" in
            1|true|yes|on)
                cron_expression=$(backup_interval_to_cron_expression "$interval_seconds")
                cat > "$cron_path" << CRON
SHELL=/bin/bash
PATH=/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin
$cron_expression root /opt/gnss-caster/backup.sh >> /var/log/gnss-caster/backup-cron.log 2>&1
CRON
                chmod 644 "$cron_path"
                printf '%s\n' "$cron_expression"
                ;;
            0|false|no|off|"")
                rm -f "$cron_path"
                ;;
            *)
                die "invalid backup cron enabled flag"
                ;;
        esac
        ;;

    certificate-info)
        cert_path="${2:-}"
        [ -n "$cert_path" ] || die "certificate path is required"

        real_cert_path=$(readlink -f -- "$cert_path" 2>/dev/null || true)
        [ -n "$real_cert_path" ] || die "certificate path not found"

        case "$real_cert_path" in
            /etc/letsencrypt/archive/*/fullchain*.pem|/etc/letsencrypt/live/*/fullchain.pem|/etc/ssl/certs/gnss-caster.crt)
                ;;
            *)
                die "unsupported certificate path"
                ;;
        esac

        [ -f "$real_cert_path" ] || die "certificate file not found"

        python3 - "$real_cert_path" << 'PYTHON_CERT_INFO'
import json
import os
import ssl
import sys
import tempfile

cert_path = sys.argv[1]
temp_cert_path = ''

try:
    with open(cert_path, 'r', encoding='utf-8', errors='ignore') as cert_file:
        pem_text = cert_file.read()

    begin_marker = '-----BEGIN CERTIFICATE-----'
    end_marker = '-----END CERTIFICATE-----'
    decode_path = cert_path

    if pem_text.count(begin_marker) > 1 and end_marker in pem_text:
        first_certificate = pem_text.split(end_marker, 1)[0] + end_marker + '\n'
        fd, temp_cert_path = tempfile.mkstemp(prefix='gnss-caster-cert-', suffix='.pem')
        with os.fdopen(fd, 'w', encoding='utf-8') as temp_cert_file:
            temp_cert_file.write(first_certificate)
        decode_path = temp_cert_path

    print(json.dumps(ssl._ssl._test_decode_cert(decode_path), ensure_ascii=True, sort_keys=True))
finally:
    if temp_cert_path:
        try:
            os.unlink(temp_cert_path)
        except Exception:
            pass
PYTHON_CERT_INFO
        ;;

    certbot-renew)
        force="${2:-0}"
        certbot_args=(certbot renew --non-interactive)
        case "$force" in
            1|true|yes|on)
                certbot_args+=(--force-renewal)
                ;;
            0|false|no|off|"")
                ;;
            *)
                die "invalid certbot force flag"
                ;;
        esac
        "${certbot_args[@]}"
        systemctl reload nginx
        ;;

    power)
        power_action="${2:-}"
        unit_name="${3:-}"
        delay_seconds="${4:-5}"
        validate_unit_name "$unit_name"
        [[ "$delay_seconds" =~ ^[0-9]+$ ]] || die "invalid delay"
        [ "$delay_seconds" -ge 1 ] && [ "$delay_seconds" -le 60 ] || die "delay must be 1..60 seconds"

        case "$power_action" in
            reboot)
                systemctl_action=reboot
                ;;
            shutdown)
                systemctl_action=poweroff
                ;;
            *)
                die "unsupported power action"
                ;;
        esac

        exec systemd-run \
            --unit "$unit_name" \
            --description "GNSS Caster host $power_action" \
            --on-active "${delay_seconds}s" \
            --property=Type=oneshot \
            systemctl "$systemctl_action"
        ;;

    *)
        die "unsupported helper action"
        ;;
esac
EOF

    chown root:root "$PRIVILEGED_HELPER"
    chmod 750 "$PRIVILEGED_HELPER"

# Least-privilege sudoers. Two forms are emitted depending on which sudo
# implementation is active:
#
#   * classic sudo - every helper subcommand is listed individually, with "*"
#     standing in for the variable arguments.
#   * sudo-rs - the default on Ubuntu 26.04 (selected over classic sudo by
#     update-alternatives). It restricts wildcards in command arguments, so the
#     rule grants the helper path itself instead. Security is unchanged in
#     practice: the helper is the real whitelist - it rejects unknown
#     subcommands and validates every argument (unit name, RFCOMM channel,
#     Bluetooth MAC, backup name) before acting.
#
# Either way the file is root:root 0440 and validated with visudo, so a
# malformed entry can never lock out sudo system-wide.
    if sudo --version 2>/dev/null | head -n 1 | grep -qi 'sudo-rs'; then
        echo "Detected sudo-rs; writing a wildcard-free sudoers rule."
        _write_sudoers_portable
    else
        _write_sudoers_restrictive
    fi

    chown root:root "$SUDOERS_FILE"
    chmod 440 "$SUDOERS_FILE"

    if ! _sudoers_file_is_valid; then
        # Belt and braces: if the stricter syntax is rejected by the installed
        # sudo implementation, fall back to the portable rule.
        echo "sudoers validation failed; falling back to the wildcard-free rule."
        _write_sudoers_portable
        chown root:root "$SUDOERS_FILE"
        chmod 440 "$SUDOERS_FILE"
        if ! _sudoers_file_is_valid; then
            echo "ERROR: generated sudoers file is invalid; removing it."
            rm -f "$SUDOERS_FILE"
            exit 1
        fi
    fi
}

_write_sudoers_restrictive() {
cat > "$SUDOERS_FILE" << EOF
Defaults:$SERVICE_USER !requiretty
$SERVICE_USER ALL=(root) NOPASSWD: \
    $PRIVILEGED_HELPER release-check, \
    $PRIVILEGED_HELPER release-status, \
    $PRIVILEGED_HELPER release-install *, \
    $PRIVILEGED_HELPER rfkill-unblock-bluetooth, \
    $PRIVILEGED_HELPER systemctl-is-active *, \
    $PRIVILEGED_HELPER systemctl-start bluetooth, \
    $PRIVILEGED_HELPER rfcomm-bind *, \
    $PRIVILEGED_HELPER rfcomm-release *, \
    $PRIVILEGED_HELPER read-rssi *, \
    $PRIVILEGED_HELPER recover-bluetooth, \
    $PRIVILEGED_HELPER recover-bluetooth-deep *, \
    $PRIVILEGED_HELPER reboot-host, \
    $PRIVILEGED_HELPER restart-service, \
    $PRIVILEGED_HELPER set-system-clock *, \
    $PRIVILEGED_HELPER systemd-job *, \
    $PRIVILEGED_HELPER write-logrotate *, \
    $PRIVILEGED_HELPER write-backup-cron *, \
    $PRIVILEGED_HELPER certificate-info *, \
    $PRIVILEGED_HELPER certbot-renew *, \
    $PRIVILEGED_HELPER power *
EOF
}

_write_sudoers_portable() {
cat > "$SUDOERS_FILE" << EOF
$SERVICE_USER ALL=(root) NOPASSWD: $PRIVILEGED_HELPER
EOF
}

_sudoers_file_is_valid() {
    command -v visudo >/dev/null 2>&1 || return 0
    visudo -cf "$SUDOERS_FILE" >/dev/null 2>&1
}

write_polkit_bluetooth_rule() {
    # Let the service account manage BlueZ over D-Bus without being root. The
    # rule is scoped twice: by subject (only the service user) and by action-id
    # prefix (only the BlueZ adapter/device/agent/profile interfaces), so it
    # cannot be used to touch any unrelated system policy.
    if [ ! -d /etc/polkit-1/rules.d ]; then
        echo "Polkit rules directory not found; skipping Bluetooth D-Bus policy rule."
        return 0
    fi

cat > "$POLKIT_RULE" << EOF
// Allow the GNSS Caster service account to manage BlueZ over D-Bus.
polkit.addRule(function(action, subject) {
    if (subject.user == "$SERVICE_USER") {
        var allowedPrefixes = [
            "org.bluez.adapter.",
            "org.bluez.device1.",
            "org.bluez.agent-manager.",
            "org.bluez.profile-manager."
        ];

        for (var i = 0; i < allowedPrefixes.length; i++) {
            if (action.id.indexOf(allowedPrefixes[i]) === 0) {
                return polkit.Result.YES;
            }
        }
    }
});
EOF
    chown root:root "$POLKIT_RULE"
    chmod 644 "$POLKIT_RULE"
}

get_nginx_backend_url() {
    local backend_port
    backend_port=$(get_config_value "web_port" "8080")
    printf 'http://127.0.0.1:%s\n' "$backend_port"
}

write_nginx_security_config() {
cat > "$NGINX_SECURITY_CONF" << 'EOF'
# GNSS Caster Nginx Security Controls
limit_req_zone $binary_remote_addr zone=gnss_login:10m rate=20r/m;
limit_req_zone $binary_remote_addr zone=gnss_api:10m   rate=120r/m;
limit_conn_zone $binary_remote_addr zone=gnss_conn_per_ip:10m;
limit_req_status 429;
EOF
}

write_nginx_http_config() {
    local backend_url
    backend_url=$(get_nginx_backend_url)
cat > "$NGINX_AVAILABLE" << EOF
# GNSS Caster Nginx Configuration (HTTP)
server {
    # default_server so requests by IP address (no matching server_name) reach
    # the caster instead of falling through to another vhost.
    listen 80 default_server;
    server_name $NGINX_SERVER_NAME;
    server_tokens off;
    client_max_body_size 2m;
    limit_conn gnss_conn_per_ip 30;

    location = /login {
        limit_req zone=gnss_login burst=10 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    # Throttle 2FA code submission to blunt TOTP brute-force (shares the login
    # rate-limit bucket per client IP; not covered by the exact "= /login" match).
    location = /login/2fa {
        limit_req zone=gnss_login burst=5 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;
    }

    location / {
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
        proxy_set_header X-Forwarded-Host \$host;

        proxy_connect_timeout 60s;
        proxy_send_timeout 60s;
        proxy_read_timeout 60s;
    }

    location /api/ {
        limit_req zone=gnss_api burst=30 nodelay;
        proxy_pass $backend_url;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
        proxy_set_header X-Forwarded-For \$proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto \$scheme;
    }

    location /health {
        access_log off;
        proxy_pass $backend_url/api/health;
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
    }
}
EOF
}

write_nginx_letsencrypt_bootstrap_config() {
    local backend_url
    backend_url=$(get_nginx_backend_url)
cat > "$NGINX_AVAILABLE" << EOF
# GNSS Caster Nginx Configuration (Let's Encrypt bootstrap)
server {
    # default_server so requests by IP address (no matching server_name) reach
    # the caster instead of falling through to another vhost.
    listen 80 default_server;
