# ----------------- RTCM MODULE -----------------
# RTCM message registry and stream manager (app/rtcm/): message metadata,
# group filtering, and cached routing of RTCM3 frames from base to rovers.
echo "Creating RTCM module..."

cat > $APP/notify.py << 'EOF'
"""Telegram notifications and remote control.

Two halves:

  * outbound - events from the caster are filtered against per-event settings
    and delivered to a chat;
  * inbound  - an optional long-polling loop accepts commands from a single
    administrator chat, so the system can be queried and muted from a phone.

Outbound events use a bounded SQLite outbox and one background worker. Network
errors cannot escape into the caster; failed local writes are counted separately.
The command polling loop remains independent of event delivery.
Uses urllib from the standard library rather than adding an HTTP dependency.
"""

import hashlib
import json
import logging
import math
import os
import sqlite3
import stat
import threading
import time
from contextlib import contextmanager
from datetime import datetime, timezone
import urllib.error
import urllib.parse
import urllib.request

logger = logging.getLogger(__name__)

API_BASE = 'https://api.telegram.org/bot{token}/{method}'

# Events the operator can switch on and off individually. The key is the
# settings key; the label is what the UI shows.
EVENT_TYPES = (
    ('notify_station_up', 'Station connected'),
    ('notify_station_down', 'Station disconnected'),
    ('notify_station_error', 'Station error'),
    ('notify_rover_connect', 'Rover connected'),
    ('notify_rover_disconnect', 'Rover disconnected'),
    ('notify_backup', 'Backup result'),
    ('notify_service', 'Service start/stop'),
)

SETTING_KEYS = (
    'telegram_enabled',
    'telegram_bot_token',
    'telegram_chat_id',
    'telegram_admin_id',
    'telegram_commands_enabled',
    'telegram_language',
) + tuple(key for key, _ in EVENT_TYPES)

DEFAULT_EVENT_STATE = {
    'notify_station_up': True,
    'notify_station_down': True,
    'notify_station_error': True,
    'notify_rover_connect': False,
    'notify_rover_disconnect': False,
    'notify_backup': True,
    'notify_service': True,
}

DEFAULT_COOLDOWN_SECONDS = 60.0

_outbox_start_lock = threading.Lock()
_poller_started = threading.Event()


def _is_true(value):
    return str(value).strip().lower() in ('1', 'true', 'yes', 'on')


def load_settings(app):
    """Read every notification setting. Returns a dict; never raises."""
    values = {}
    available = False
    try:
        from app.db.models import SystemSetting, db

        with app.app_context():
            rows = SystemSetting.query.filter(
                SystemSetting.key.in_(SETTING_KEYS)
            ).all()
            values = {row.key: str(row.value or '') for row in rows}
            available = True
            db.session.remove()
    except Exception as settings_error:
        logger.debug(f'Notification settings unavailable: {settings_error}')

    settings = {
        'available': available,
        'enabled': _is_true(values.get('telegram_enabled', 'false')),
        'token': values.get('telegram_bot_token', '').strip(),
        'chat_id': values.get('telegram_chat_id', '').strip(),
        'admin_id': values.get('telegram_admin_id', '').strip(),
        'commands_enabled': _is_true(values.get('telegram_commands_enabled', 'false')),
        'language': 'ru' if values.get('telegram_language', '').strip().lower() == 'ru' else 'en',
        'events': {},
    }
    for key, _label in EVENT_TYPES:
        if key in values and values[key] != '':
            settings['events'][key] = _is_true(values[key])
        else:
            settings['events'][key] = DEFAULT_EVENT_STATE.get(key, True)
    return settings


def _set_setting(app, key, value):
    """Persist one setting. Used by chat commands."""
    from app.db.models import SystemSetting, db

    with app.app_context():
        row = SystemSetting.query.filter_by(key=key).first()
        if row is None:
            row = SystemSetting(key=key, value=str(value), description='')
            db.session.add(row)
        else:
            row.value = str(value)
        db.session.commit()
        db.session.remove()


def _call(token, method, params, timeout=15):
    payload = urllib.parse.urlencode(params).encode('utf-8')
    request = urllib.request.Request(
        API_BASE.format(token=token, method=method),
        data=payload,
        headers={'Content-Type': 'application/x-www-form-urlencoded'},
    )
    http_code = None
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            body = response.read(65536)
    except urllib.error.HTTPError as http_error:
        http_code = http_error.code
        # Telegram explains itself in the response body - "chat not found",
        # "Unauthorized", "bot was blocked by the user". Without reading it the
        # operator only sees "HTTP Error 400: Bad Request", which says nothing
        # about what to fix.
        try:
            body = http_error.read(65536)
        except Exception:
            return {'ok': False, 'error_code': http_code, 'description': f'HTTP {http_code}'}

    try:
        parsed = json.loads(body.decode('utf-8', 'replace'))
        if not isinstance(parsed, dict) or not isinstance(parsed.get('ok'), bool):
            raise ValueError('invalid Telegram response')
        if http_code is not None:
            parsed['ok'] = False
            parsed.setdefault('error_code', http_code)
        return parsed
    except (ValueError, TypeError):
        return {'ok': False, 'error_code': http_code, 'description': 'unparseable response'}


TELEGRAM_HINTS = {
    'chat not found': (
        'Telegram does not know this chat. Open a chat with your bot and send it '
        'any message first - bots cannot write to someone who never wrote to them.'
    ),
    'unauthorized': 'The bot token is wrong. Copy it again from @BotFather.',
    'bot was blocked': 'The bot is blocked in that chat. Unblock it and try again.',
    'chat_id is empty': 'No chat ID was set.',
}


def _explain(description):
    """Turn Telegram's terse reason into something actionable."""
    lowered = str(description or '').lower()
    for needle, hint in TELEGRAM_HINTS.items():
        if needle in lowered:
            return f'{description} - {hint}'
    return str(description or 'unknown error')


# Buttons for the common actions, so nothing has to be typed on a phone in the field.
MAIN_KEYBOARD = {
    'inline_keyboard': [
        [
            {'text': '\u2705 Ready?', 'callback_data': 'ready'},
            {'text': '\U0001f4ca Status', 'callback_data': 'status'},
        ],
        [
            {'text': '\U0001f4e1 Rovers', 'callback_data': 'rovers'},
            {'text': '\U0001f514 Alerts', 'callback_data': 'events'},
        ],
        [
            {'text': '\U0001f5a5 Server', 'callback_data': 'server'},
            {'text': '\U0001f4be Backup now', 'callback_data': 'backup'},
        ],
        [
            {'text': '\U0001f507 Mute', 'callback_data': 'mute'},
            {'text': '\U0001f514 Unmute', 'callback_data': 'unmute'},
        ],
        [
            {'text': '\u21bb Restart service', 'callback_data': 'restart'},
            {'text': '\U0001f501 Reboot', 'callback_data': 'reboot'},
        ],
        [
            {'text': '\u2753 Help', 'callback_data': 'help'},
        ],
    ]
}


def _post_message(token, chat_id, text, keyboard=None):
    params = {
        'chat_id': chat_id,
        'text': text,
        'disable_web_page_preview': 'true',
    }
    if keyboard:
        params['reply_markup'] = json.dumps(keyboard)

    parsed = _call(token, 'sendMessage', params)
    if parsed.get('ok'):
        return True, ''
    return False, _explain(parsed.get('description'))


class NotificationOutbox:
    """Bounded, at-least-once event delivery. Never holds a DB lock during HTTP.

    SQLite is separate from the configuration DB so restoring an old backup does
    not replay its alerts. No token/chat ID or arbitrary remote error is stored.
    A logical clock anchored to monotonic time avoids GNSS/NTP clock jumps within
    a process; its high-water mark also prevents backward jumps after a restart.
    """
    CAPACITY = 200
    HISTORY = 200
    MAX_AGE = 1800
    MAX_ATTEMPTS = 8
    LEASE = 90
    SEND_INTERVAL = 3.1  # Conservative for a group as well as a private chat.

    def __init__(self, app):
        self.app = app
        self.path = os.path.join(app.config['INSTANCE_DIR'], 'notifications.sqlite')
        self.lock = threading.RLock()
        self.wake = threading.Event()
        self.stop = threading.Event()
        self.thread = None
        self.write_failures = 0
        self.worker_error = False
        self.anchor = time.time()
        self.monotonic_start = time.monotonic()
        # Refuse symlinks and shared files; service-only data, not a root helper.
        fd = os.open(self.path, os.O_CREAT | os.O_RDWR | getattr(os, 'O_NOFOLLOW', 0), 0o600)
        try:
            info = os.fstat(fd)
            if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
                raise OSError('Unsafe notification database')
            if os.name == 'posix' and (info.st_uid not in (0, os.geteuid()) or
                                       info.st_gid != os.getegid() or info.st_mode & 0o117):
                raise OSError('Unsafe notification database permissions')
        finally:
            os.close(fd)
        with self.database() as conn:
            conn.executescript('''
                CREATE TABLE IF NOT EXISTS outbox (
                    id INTEGER PRIMARY KEY, event TEXT, event_key TEXT, destination TEXT NOT NULL,
                    text TEXT NOT NULL, created REAL NOT NULL, occurred REAL NOT NULL,
                    due REAL NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
                    cooldown REAL NOT NULL, state TEXT NOT NULL DEFAULT 'pending',
                    error TEXT NOT NULL DEFAULT '');
                CREATE TABLE IF NOT EXISTS delivered (event_key TEXT PRIMARY KEY, sent REAL NOT NULL);
                CREATE TABLE IF NOT EXISTS queue_meta (key TEXT PRIMARY KEY, value REAL NOT NULL);
                CREATE INDEX IF NOT EXISTS outbox_state ON outbox(state, id);
            ''')
            self.anchor = max(self.anchor, self.meta(conn, 'clock'))

    def now(self):
        return self.anchor + time.monotonic() - self.monotonic_start

    @contextmanager
    def database(self):
        with self.lock:
            conn = sqlite3.connect(self.path, timeout=0.05)
            conn.row_factory = sqlite3.Row
            try:
                conn.execute('PRAGMA synchronous=FULL')
                conn.execute('PRAGMA secure_delete=ON')
                conn.execute('PRAGMA max_page_count=2048')
                conn.execute('BEGIN IMMEDIATE')
                yield conn
                conn.commit()
            except BaseException:
                conn.rollback()
                raise
            finally:
                conn.close()

    @staticmethod
    def meta(conn, key):
        row = conn.execute('SELECT value FROM queue_meta WHERE key=?', (key,)).fetchone()
        return float(row[0]) if row else 0.0

    @staticmethod
    def put_meta(conn, key, value):
        conn.execute('INSERT OR REPLACE INTO queue_meta VALUES (?,?)', (key, value))

    def count(self, conn, key, amount=1):
        self.put_meta(conn, key, self.meta(conn, key) + amount)
        self.put_meta(conn, 'clock', self.now())

    @staticmethod
    def destination(settings):
        return hashlib.sha256(json.dumps([settings['token'], settings['chat_id']]).encode()).hexdigest()

    @staticmethod
    def enabled(settings, event=None):
        return bool(settings['enabled'] and settings['token'] and settings['chat_id']
                    and (not event or settings['events'].get(event, True)))

    def finish(self, conn, item, state, error=''):
        conn.execute('UPDATE outbox SET state=?,text=?,error=? WHERE id=?',
                     (state, '', error, item['id']))
        self.count(conn, state)
        if state == 'delivered':
            self.put_meta(conn, 'last_success', time.time())
            if item['event_key']:
                conn.execute('INSERT OR REPLACE INTO delivered VALUES (?,?)', (item['event_key'], self.now()))

    def prune(self, conn):
        now = self.now()
        # A leased HTTP request is allowed to finish; expired leases can retry.
        conn.execute("UPDATE outbox SET state='pending' WHERE state='sending' AND due<=?", (now,))
        for row in conn.execute("SELECT * FROM outbox WHERE state='pending' AND created<=?", (now-self.MAX_AGE,)).fetchall():
            self.finish(conn, row, 'expired', 'Notification expired')
        conn.execute("DELETE FROM outbox WHERE state NOT IN ('pending','sending') AND id NOT IN "
                     "(SELECT id FROM outbox WHERE state NOT IN ('pending','sending') ORDER BY id DESC LIMIT ?)", (self.HISTORY,))
        conn.execute('DELETE FROM delivered WHERE sent<?', (now-86400,))
        conn.execute('DELETE FROM delivered WHERE event_key NOT IN (SELECT event_key FROM delivered ORDER BY sent DESC LIMIT 1000)')

    def enqueue(self, text, event, event_key, cooldown):
        settings = load_settings(self.app)
        if not settings.get('available', True):
            raise RuntimeError('Notification settings unavailable')
        if not self.enabled(settings, event):
            return False
        destination = self.destination(settings)
        # Hash identifiers too: names and destinations need not appear in status.
        key = hashlib.sha256((destination + str(event_key)).encode()).hexdigest() if event_key else None
        cooldown = float(cooldown)
        cooldown = max(0, min(cooldown, 86400)) if math.isfinite(cooldown) else DEFAULT_COOLDOWN_SECONDS
        with self.database() as conn:
            self.prune(conn)
            if key:
                pending = conn.execute("SELECT 1 FROM outbox WHERE event_key=? AND state IN ('pending','sending')", (key,)).fetchone()
                sent = conn.execute('SELECT sent FROM delivered WHERE event_key=?', (key,)).fetchone()
                if pending or (sent and self.now()-sent[0] < cooldown):
                    self.count(conn, 'suppressed')
                    return False
            size = conn.execute("SELECT COUNT(*) FROM outbox WHERE state IN ('pending','sending')").fetchone()[0]
            if size >= self.CAPACITY:
                self.count(conn, 'overflow')
                return False
            now = self.now()
            conn.execute('INSERT INTO outbox(event,event_key,destination,text,created,occurred,due,cooldown) VALUES(?,?,?,?,?,?,?,?)',
                         (event, key, destination, str(text)[:4000], now, time.time(), now, cooldown))
            self.count(conn, 'queued')
        self.wake.set()
        return True

    def deliver(self, item, settings):
        text = translate_bot(item['text'], settings.get('language', 'en'))
        if self.now()-item['created'] >= 60:
            stamp = datetime.fromtimestamp(item['occurred'], timezone.utc).strftime('%Y-%m-%d %H:%M:%S UTC')
            prefix = 'Событие от' if settings.get('language') == 'ru' else 'Event recorded at'
            text = f'[{prefix} {stamp}]\n{text}'
        # Telegram's character limit: count UTF-16 units conservatively for emoji.
        text = text.encode('utf-16-le')[:8000].decode('utf-16-le', 'ignore')
        try:
            result = _call(settings['token'], 'sendMessage', {
                'chat_id': settings['chat_id'], 'text': text, 'disable_web_page_preview': 'true'})
        except Exception:
            return False, True, 0, 'Telegram connection failed'
        if result.get('ok') is True:
            return True, False, 0, ''
        code = result.get('error_code')
        if code == 429:
            try:
                delay = float((result.get('parameters') or {}).get('retry_after', 5))
                if not math.isfinite(delay) or delay < 0:
                    delay = 5
            except (TypeError, ValueError, AttributeError):
                delay = 5
            return False, True, delay, 'Telegram rate limit'
        code = code if isinstance(code, int) else None
        permanent = code is not None and 400 <= code < 500 and code not in (408, 425)
        error = {400: 'Telegram rejected the message', 401: 'Telegram token rejected',
                 403: 'Telegram access denied'}.get(code, 'Telegram delivery failed')
        return False, not permanent, 0, error

    def process_one(self):
        settings = load_settings(self.app)
        if not settings.get('available', True):
            raise RuntimeError('Notification settings unavailable')
        with self.database() as conn:
            self.prune(conn)
            # Preserve event order: a delayed offline notice cannot follow its
            # newer recovery notice. Cancel messages when disabled or rerouted.
            for item in conn.execute("SELECT * FROM outbox WHERE state='pending'").fetchall():
                if not self.enabled(settings, item['event']) or item['destination'] != self.destination(settings):
                    self.finish(conn, item, 'cancelled', 'Notification settings changed')
            item = conn.execute("SELECT * FROM outbox WHERE state IN ('pending','sending') ORDER BY id LIMIT 1").fetchone()
            if item is None:
                return False
            now = self.now()
            if item['state'] == 'sending' or max(item['due'], self.meta(conn, 'pace')) > now:
                return False
            if item['attempts'] >= self.MAX_ATTEMPTS:
                self.finish(conn, item, 'failed', 'Telegram retry limit reached')
                return True
            conn.execute("UPDATE outbox SET state='sending',attempts=attempts+1,due=? WHERE id=?", (now+self.LEASE, item['id']))
            self.put_meta(conn, 'clock', now)
            self.put_meta(conn, 'pace', now+self.SEND_INTERVAL)
        ok, retryable, delay, error = self.deliver(item, settings)
        with self.database() as conn:
            self.put_meta(conn, 'clock', self.now())
            if ok:
                self.finish(conn, item, 'delivered')
            elif retryable and item['attempts']+1 < self.MAX_ATTEMPTS:
                delay = max(delay, min(300, 5 * 2 ** item['attempts']))
                due = self.now()+delay
                conn.execute("UPDATE outbox SET state='pending',due=?,error=? WHERE id=?", (due, error, item['id']))
                self.put_meta(conn, 'pace', max(self.meta(conn, 'pace'), due))
                self.count(conn, 'retries')
            else:
                self.finish(conn, item, 'failed', error)
                # A final 429 still applies to the following event.
                self.put_meta(conn, 'pace', max(self.meta(conn, 'pace'), self.now()+delay))
            self.prune(conn)
        return True

    def start(self):
        with self.lock:
            if self.thread and self.thread.is_alive():
                return
            def loop():
                while not self.stop.is_set():
                    self.wake.clear()
                    try:
                        worked = self.process_one()
                        self.worker_error = False
                    except Exception:
                        if not self.worker_error:
                            logger.warning('Telegram outbox unavailable; delivery will retry')
                        self.worker_error = True
                    self.wake.wait(5 if self.worker_error else (self.SEND_INTERVAL if worked else 10))
            self.thread = threading.Thread(target=loop, daemon=True, name='telegram-outbox')
            self.thread.start()

    def status(self):
        with self.database() as conn:
            pending = conn.execute("SELECT COUNT(*),MIN(created),MIN(due) FROM outbox WHERE state IN ('pending','sending')").fetchone()
            last = conn.execute('SELECT state,error FROM outbox ORDER BY id DESC LIMIT 1').fetchone()
            counts = {key: int(self.meta(conn, key)) for key in ('queued','delivered','failed','expired','cancelled','overflow','suppressed','retries')}
            first = conn.execute("SELECT error FROM outbox WHERE state IN ('pending','sending') ORDER BY id LIMIT 1").fetchone()
            return dict(available=True, worker_running=bool(self.thread and self.thread.is_alive()),
                        worker_error=self.worker_error, write_failures=self.write_failures,
                        pending=pending[0], capacity=self.CAPACITY, counts=counts,
                        oldest_age_seconds=max(0, self.now()-pending[1]) if pending[1] else 0,
                        next_attempt_seconds=max(0, max(pending[2], self.meta(conn, 'pace'))-self.now()) if pending[2] else 0,
                        last_success=self.meta(conn, 'last_success') or None,
                        last_error=first['error'] if first else (last['error'] if last and last['state']=='failed' else ''))


def _get_outbox(app):
    with _outbox_start_lock:
        outbox = app.extensions.get('telegram_outbox')
        if outbox is None:
            outbox = NotificationOutbox(app)
            app.extensions['telegram_outbox'] = outbox
        return outbox


def start_outbox(app):
    outbox = _get_outbox(app)
    outbox.start()
    return outbox


def outbox_status(app):
    try:
        outbox = app.extensions.get('telegram_outbox')
        return outbox.status() if outbox else {'available': False}
    except Exception:
        return {'available': False}


def send(app, text, event=None, event_key=None, cooldown=DEFAULT_COOLDOWN_SECONDS):
    """Persist an event, without waiting for HTTP. Never raises into the caster."""
    if not app or not text:
        return
    try:
        outbox = _get_outbox(app)
        outbox.enqueue(text, event, event_key, cooldown)
    except Exception:
        outbox = app.extensions.get('telegram_outbox')
        if outbox:
            outbox.write_failures += 1
        logger.warning('Telegram notification could not be saved')
        return
    try:
        outbox.start()
    except Exception:
        outbox.worker_error = True
        logger.warning('Telegram worker not started; saved events remain queued')


def send_test(app, text='GNSS Caster: test notification'):
    """Synchronous send used by the "Send test message" button."""
    settings = load_settings(app)
    if not settings['token'] or not settings['chat_id']:
        return False, translate_bot('Bot token and chat ID are both required', settings.get('language', 'en'))
    if not settings['enabled']:
        return False, translate_bot('Notifications are disabled', settings.get('language', 'en'))
    try:
        return _post_message(settings['token'], settings['chat_id'], translate_bot(text, settings.get('language', 'en')))
    except Exception as send_error:
        return False, str(send_error)


