echo "Creating web application..."

cat > $APP/web/factory.py << 'EOF'
"""
Flask Application Factory
Creates and configures the Flask application
"""
import os
import time
import logging
import json
import subprocess
import re
import ssl
import shutil
import tempfile
import secrets
import glob
import threading
import uuid
import hashlib
import csv
import io
from functools import wraps
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime
from types import SimpleNamespace
from flask import Flask, render_template, request, redirect, url_for, jsonify, send_file, session, g, Response
from flask_login import LoginManager, login_user, login_required, logout_user, current_user
from flask_bcrypt import Bcrypt
from sqlalchemy import text
from werkzeug.middleware.proxy_fix import ProxyFix
import yaml
from app.db.models import db, Admin, BaseStation, MountPoint, Rover, LogEntry, RTCMSetting, SystemSetting, ReceiverConfigVersion, CommandLog, ApiToken, write_private_text
from app.version import __version__
from app.rtcm.registry import (
    RTCM_DESCRIPTIONS,
    get_all_messages_by_group,
    get_groups,
