        @app.route('/api/mountpoints/create', methods=['POST'])
        @login_required
        def api_create_mountpoint():
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                data = request.json
                if not data or 'name' not in data or 'base_id' not in data:
                    return jsonify({'error': 'Missing required fields'}), 400

                # NTRIP-safe mountpoint name: it is embedded verbatim into the
                # sourcetable ("STR;<name>;...") and into request URLs, so
                # separators (";", whitespace, CR/LF) would corrupt the protocol
                # stream. Restrict to a conservative charset.
                mp_name = str(data['name'] or '').strip()
                if not re.fullmatch(r'[A-Za-z0-9_-]{1,64}', mp_name):
                    return jsonify({'error': 'Mountpoint name must be 1-64 characters: letters, digits, "_" or "-"'}), 400
                data['name'] = mp_name

                # Check if mountpoint already exists
                existing = MountPoint.query.filter_by(name=data['name']).first()
                if existing:
                    return jsonify({'error': 'Mountpoint with this name already exists'}), 400
                
                # Check if base station exists
                base_station = BaseStation.query.get(data['base_id'])
                if not base_station:
                    return jsonify({'error': 'Base station not found'}), 400
                
                mountpoint = MountPoint(
                    name=data['name'],
                    base_id=data['base_id'],
                    description=data.get('description', ''),
                    is_active=data.get('is_active', True),
                    rtcm_settings=json.dumps(data.get('rtcm_settings', {}))
                )
                
                db.session.add(mountpoint)
                db.session.commit()
                stream_manager.invalidate_filter_cache()
                return jsonify({'message': 'Mountpoint created', 'id': mountpoint.id}), 201
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error creating mountpoint: {e}")
                return jsonify({'error': str(e)}), 500
        
