        @login_required
        def api_system_backup_restore():
            try:
                role_error = _require_admin_role()
                if role_error:
                    return role_error

                data = request.json or {}
                filename = data.get('filename', '')
                job = _schedule_restore_script(filename, str(data.get('passphrase', '') or ''))
                client_ip = _get_client_ip()
                now_ts = int(time.time())

                db.session.add(LogEntry(
                    level='WARNING',
                    module='maintenance',
                    message=(
                        f'User {current_user.username} scheduled a restore from '
                        f'{job.get("filename", "backup archive")} '
                        f'({job.get("unit_name", "systemd job")})'
                    ),
                    timestamp=now_ts,
                    ip_address=client_ip
                ))
                db.session.commit()

                return jsonify({
                    'message': (
                        f'Restore job started for {job.get("filename", "the selected backup")}. '
                        'The web interface may disconnect while the service restarts.'
                    ),
                    'job': job,
                }), 202
            except Exception as e:
                db.session.rollback()
                logger.error(f"Error restoring backup: {e}")
                return jsonify({'error': str(e)}), 500

