        @app.route('/api/site_points/<int:point_id>/apply/<int:station_id>', methods=['POST'])
        @login_required
        def api_site_point_apply(point_id, station_id):
            """Copy a saved point onto a station's manual position."""
            try:
                role_error = _require_operator_role()
                if role_error:
                    return role_error

                from app.db.models import SitePoint

                point = db.session.get(SitePoint, point_id)
                if point is None:
                    return jsonify({'error': 'Point not found'}), 404

                station = db.session.get(BaseStation, station_id)
                if station is None:
                    return jsonify({'error': 'Base station not found'}), 404

                station.position_mode = 'manual'
                station.manual_lat = point.latitude
                station.manual_lon = point.longitude
                station.manual_alt = point.altitude
                station.antenna_height = point.antenna_height
                station.add_antenna_height = bool(point.add_antenna_height)
                station.updated_at = int(time.time())
                point.last_used_at = int(time.time())
                db.session.commit()

                return jsonify({
                    'success': True,
                    'message': (
                        f'Station "{station.name}" now uses point "{point.name}". '
                        'Press Apply Config to push it to the receiver.'
                    ),
                })
            except Exception as e:
                db.session.rollback()
                logger.error(f'Error applying site point: {e}')
                return jsonify({'error': str(e)}), 500

